function ico(n,cls){return `<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"${cls?` class="${cls}"`:''}>${ICO[n]||''}</svg>`}
function paintIcons(root){for(const el of (root||document).querySelectorAll('[data-ico]')){if(el.dataset.icoDone)continue;el.dataset.icoDone=1;el.insertAdjacentHTML('afterbegin',el.dataset.ico==='bomb'?`<svg viewBox="0 0 24 24" width="26" height="26" aria-hidden="true">${ICO.bomb}</svg>`:ico(el.dataset.ico))}}
// ---------- seats and views ----------
function humans(){return G?G.seats.filter(q=>q.human).map(q=>q.i):[]}
function isHuman(s){return !!(G&&G.seats[s]&&G.seats[s].human)}
function modeOf(){if(NET.on)return NET.mySeat>=0?'solo':'watch';const h=humans().length;return h===0?'watch':h===1?'solo':'hot'}
function nm(s){return G&&G.seats[s]?G.seats[s].nm:'?'}
// ---- newcomer-review additions (all new UI strings live here) ----
const noGear=()=>!!G&&G.mission===1;
const GLOSSARY=[['Stand','The rack in front of you that holds your wires, sorted from low to high. Only you see the faces of your own stand. With 2 or 3 players some people hold two stands.'],
 ['Foreman','The player marked with a star (★). Starts the job and takes the first turn; the turn then passes clockwise.'],
 ['Info token','A marker placed in front of a wire that tells everyone its number (or, in some jobs, only even/odd or "not this number").'],
 ['Tag','To tag a wire is to put an info token in front of it. Everyone places one opening token at the start; a missed cut tags the wire that was pointed at.'],
 ['Fuse','The bomb timer. Every miss burns one step; when no step is left, the bomb goes off.'],
 ['Dual cut','Point at one wire of a crewmate and say a number you hold. If it matches, both wires are cut. If not, it is a miss.'],
 ['Solo cut','Cut every wire of one value yourself, when you hold all the wires of that value still uncut. It never fails.'],
 ['Equipment (gear)','Cards on the table that unlock when the crew cuts certain numbers. Some jobs have none.'],
 ['Personal tool','A tool on your crew card (for example the Twin Probe) that you can use once per job.'],
 ['Validation token','Goes on the track when all four wires of a value are cut: that value is finished.'],
 ['Red wire','Never match a red wire. Pointing at one blows up the bomb. A player holding only reds reveals them and is done.']];
const GLOSS_HTML='<h3>Glossary</h3><dl class="gloss">'+GLOSSARY.map(g=>`<dt>${g[0]}</dt><dd>${g[1]}</dd>`).join('')+'</dl>';
function hintify(t){return String(t).replace(/The fuse is lit\./,'Round 1 begins: the foreman (★) takes the first turn.').replace(/(reveals \d+ red wires? and is done\.)/,'$1 (a player who holds only red wires shows them and is finished)').replace(/(validation token (\d+) goes on the track\.)/,'$1 (every wire of value $2 is cut, so $2 is finished)')}
const DOING={infoStd:'choosing an opening info token',tagPick:'choosing which wire gets the info token',pickMatch:'choosing which wire to cut',swapPick:'choosing a wire to trade',designate:'choosing who must cut',declare:'turning over a number card'};
function doing(q){return (q&&DOING[q.kind])||'answering a question'}
function wLabel(u){const f=findU(u);if(!f)return {s:0,k:0,t:'?'};const sl=G.st[f.s].w[f.k];const v=sl&&ownerOf(f.s)===(UI.V&&UI.V.seat)?cv(sl.id):null;return {s:f.s,k:f.k,t:`wire ${LET(f.k)}${v!=null?' ('+VNm(v)+')':''}`}}
function decider(){if(!G||G.over)return -1;return sideToAct()}
// hot-seat: the device must change hands when a human other than the holder must decide
function passTo(){if(NET.on||modeOf()!=='hot'||!G||G.over)return -1;if(UI.offSeat!=null)return UI.offSeat===UI.holder?-1:UI.offSeat;const s=decider();
  if(s>=0&&isHuman(s)&&s!==UI.holder)return s;
  if(s<0&&(G.step==='claim'||G.step==='snip')){const h=humans();if(UI.holder<0&&h.length)return h[0]}
  if(UI.holder<0){const h=humans();return h.length?h[0]:-1}return -1}
// the seat whose eyes the page shows: solo = the human, hot-seat = the holder (none while passing), watch = nobody
function viewer(){if(NET.on)return NET.mySeat;const m=modeOf();if(m==='watch')return -1;if(m==='solo')return humans()[0];if(passTo()>=0)return -1;return UI.holder}
// the seat at the bottom of the table
function kitMe(){if(NET.on&&NET.mySeat<0)return 0;const v=viewer();if(v>=0)return v;const p=passTo();if(p>=0)return p;const h=humans();return h.length?h[0]:0}
// a spectator view (watch mode with x-ray, or the neutral hot-seat view with every hidden wire turned away)
function spectatorView(xray){const K=knowledge(kitMe());
  for(const st of K.stands){st.mine=false;const S=G.st[st.i];st.slots.forEach((x,k)=>{const sl=S.w[k];if(xray){x.v=cv(sl.id);x.s=WIRES[sl.id].s;x.c=WIRES[sl.id].c}else if(!x.cut){x.v=null;x.s=null;x.c=null}})}
  K.seat=-1;K.legal=null;K.q=G.q?{who:G.q.who,kind:G.q.kind}:null;K.off=[];if(!xray)for(const q of K.seats){q.cards=G.mission===65?q.cards:null;if(q.con&&G.ms.mole)q.con='?'}return K}
function view(){const v=viewer();if(v>=0)return knowledge(v);return spectatorView(modeOf()==='watch'&&UI.xray&&!NET.on)}
function posOf(s){return G.pos[s]}
function seatStands(seat){return standsOf(seat).slice().sort((a,b)=>a-b)}
function wireName(si,k,V){const own=ownerOf(si);const ss=seatStands(own);const two=ss.length>1;const who=V&&own===V.seat?'your':nm(own)+'\'s';return `${who} wire ${LET(k)}${two?' (stand '+(ss.indexOf(si)+1)+')':''}`}
// engine texts say "stand 3, slot 2": rewrite to the letters on the table
function nice(t,V){return hintify(t).replace(/Miss: none of those is ([^.]+)\./g,'Miss: wrong number (not $1).').replace(/\b(Cut|Tag) slot (\d+)\b/g,(m,a,b)=>a+' wire '+LET(+b-1)).replace(/stand (\d+),? slots? ([\d,]+)/g,(m,a,b)=>{const si=+a-1;if(!G.st[si])return m;const ks=b.split(',').map(x=>+x-1);return ks.length>1?wireName(si,ks[0],V).replace(/wire [A-Z]/,'wires '+ks.map(LET).join(', ')):wireName(si,ks[0],V)})}
// ---------- the one entry point for human input (stage 3 intercepts here) ----------
function act(m,seat){if(!G||G.over)return {success:false,error:'no game'};if(seat==null)seat=viewer();
  if(!isHuman(seat))return {success:false,error:'not a human seat'};
  if(typeof window.NET_INTERCEPT==='function'){const r=window.NET_INTERCEPT(m,seat);if(r)return r}
  const err=legal(m,seat);if(err){toast(err);sfx('buzzer');return {success:false,error:err}}
  if(isClient()){if(seat!==NET.mySeat||(NET.pend===G.logN&&Date.now()-NET.pendT<2500))return {success:false,error:'wait'};NET.pend=G.logN;NET.pendT=Date.now();UI.sel=null;sfx('click');netSend(m);refresh();return {success:true,sent:1}}
  UI.sel=null;UI.offSeat=null;UI.lastActor=seat;if(modeOf()==='solo'){UI.aiNotBefore=Date.now()+1700/UI.speed}sfx('click');return applyMove(m,seat)}
function applyMove(m,seat){const r=performMove(m,seat);if(!r.success){console.error('move rejected: '+r.error+' '+JSON.stringify(m));refresh()}return r}
// ---------- snapshots: what changed since the last refresh (drives sounds, effects and the result banner) ----------
function snap(){const cut=new Set(),tok={};for(const s of G.st)for(const x of s.w){if(x.cut)cut.add(x.u);tok[x.u]=x.tok.length}let side=0;for(const s of G.st)side+=s.side.length;
  return {g:G.seed+':'+G.mission,logN:G.logN,dial:G.dial,cut,tok,side,valid:G.valid.length,over:!!G.over,rf:G.ms.rf?G.ms.rf.at:null,turn:G.turn}}
// whose turn a log turn number was (from the "— X's turn —" line); -1 for the opening
// a later result on the same turn of yours (the tag after a miss, the fuse step) belongs to the same card
function turnActor(t){const l=G.log.find(x=>x.turn===t&&x.c==='turn');if(!l)return -1;const m=/— (.+)'s turn —/.exec(l.t);const q=m&&G.seats.find(x=>x.nm===m[1]);return q?q.i:-1}
function diffFx(a,b){if(!a||a.g!==b.g){UI.lastActor=null;return}const newLog=G.log.filter(l=>l.i>a.logN).reverse();if(!newLog.length&&b.dial===a.dial){UI.lastActor=null;return}
  const newCut=[...b.cut].filter(u=>!a.cut.has(u));const newTok=Object.keys(b.tok).filter(u=>b.tok[u]>(a.tok[u]||0)).map(Number);
  const txt=newLog.map(l=>l.t).join(' ');
  const dialDown=b.dial!=null&&a.dial!=null&&b.dial<a.dial||(b.rf!=null&&a.rf!=null&&b.rf>a.rf&&/miss/i.test(txt)),dialUp=b.dial!=null&&a.dial!=null&&b.dial>a.dial;
  let kind=null;
  if(b.over&&!a.over)kind=G.over.win?'win':'boom';
  else if(/Miss|miss:|missed|wrong/.test(txt)&&dialDown||(/Miss/.test(txt)&&!newCut.length))kind='miss';
  else if(newCut.length&&/solo/i.test(txt))kind='solo';
  else if(newCut.length&&/Hit!|cuts|reveals|all at once|cut at once/i.test(txt))kind=/reveals/.test(txt)?'reveal':'hit';
  else if(dialUp)kind='phew';
  else if(newCut.length)kind='hit';
  else if(dialDown)kind='miss';
  UI.lastActor=null;
  UI.lastKind=kind;
  if(!ANIM)return;
  if(kind==='hit'||kind==='solo'||kind==='reveal'){newCut.forEach((u,i)=>fx('cut',u));sfx(kind==='solo'?'solo_cut':kind==='reveal'?'reveal':newCut.length>1?'double_cut':'cut')}
  if(kind==='miss'){fx('miss',newTok[0]!=null?newTok[0]:null);sfx('wrong');sfx('dial',{at:.25});if(newTok.length)sfx('info',{at:.45});
    if(G.dial===1)setTimeout(()=>sfx('tick_last'),700);else sfx('tick',{at:.6})}
  if(kind==='phew'){fx('phew');sfx('phew')}
  if(b.valid>a.valid){fx('coin');sfx('validate',{at:.35})}
  if(/is unlocked|turns up/.test(txt))sfx('gadget',{at:.2});
  if(/Sweep for|sweeps/.test(txt))sfx('scanner');
  if(/Handsets|trade|pulls/.test(txt)&&!kind)sfx('flip');
  if(kind==='win'){musicStop(.4);setTimeout(()=>{if(G&&G.over)musicSlot('victory')},1600);sndLoop('clock_loop',false);fx('win');sfx('phew');sfx('win',{at:.8})}
  if(kind==='boom'){musicStop(.3);setTimeout(()=>{if(G&&G.over)musicSlot('defeat')},2200);sndLoop('clock_loop',false);fx('boom',newTok[0]!=null?newTok[0]:null);sfx('boom');sfx('lose',{at:1.6})}}
// ---------- refresh: called by the engine after every move ----------
function refresh(){if(!G||!UI.started)return;try{if(window.PerfHUD)PerfHUD.wake()}catch(e){}
  const s=snap();diffFx(UI.prev,s);UI.prev=s;
  saveNow();
  if(G.prompt&&(!UI.lastPrompt||UI.lastPrompt.t!==G.prompt.t||UI.lastPrompt.say!==G.prompt.say)){UI.lastPrompt=Object.assign({},G.prompt);UI.holdUntil=Date.now()+(ANIM?1500:0);sfx('radar');if(UI.rt)toast(G.prompt.say)}
  if(G.over&&!UI.campDone){UI.campDone=1;recordResult();try{campOver()}catch(e){console.error(e)}}
  const V=view();UI.V=V;
  if(UI.sel&&!selValid(V))UI.sel=null;
  renderTable(V);renderOpenDrawer();audioMood(V);
  const need=humanNeeded();
  if(need&&need!==UI.lastNeed){UI.lastNeed=need;if(ANIM)sfx('turn')}if(!need)UI.lastNeed=null;
  schedule();netAfter();try{hlpAfter()}catch(e){console.error(e)}}
function humanNeeded(){if(!G||G.over)return null;const p=passTo();if(p>=0)return 'pass'+p;const v=viewer();if(v<0)return null;const s=decider();if(s===v)return 'me'+G.turn+':'+(G.q?G.q.kind:G.step);return null}
function saveNow(){if(NET.on)return;try{if(G&&!G.over&&humans().length)localStorage.setItem(SAVE,JSON.stringify({G,ui:{holder:UI.holder,rt:UI.rt,camp:UI.camp?UI.camp.id:null}}));else if(G&&G.over)localStorage.removeItem(SAVE)}catch(e){}}
// ---------- the computer crew ----------
function aiHeld(){return !!(G&&!G.over&&UI.brief)}
function schedule(){if(isClient()||UI.aiT||!G||G.over||UI.pause||!UI.started||aiHeld())return;
  if(UI.sel&&UI.sel.off)return;                 // a human is choosing an any-time card: wait
  const s=decider();const open=G.step==='claim'||G.step==='snip';
  if(s>=0&&isHuman(s)&&!open){if(UI.offChecked!==G.logN){UI.offChecked=G.logN;const st=aiStep();if(st&&!isHuman(st.seat))UI.aiT=setTimeout(()=>{UI.aiT=null;if(G&&!G.over&&!UI.pause&&!legal(st.m,st.seat))applyMove(st.m,st.seat)},ANIM?AIDELAY/UI.speed:0)}return}
  if(passTo()>=0&&!open)return;
  let d=ANIM?AIDELAY/UI.speed:0;if(open&&humans().length&&ANIM)d=Math.max(d,2200/UI.speed);if(ANIM&&UI.aiNotBefore)d=Math.max(d,UI.aiNotBefore-Date.now());
  if(!ANIM&&open&&humans().length)d=AIDELAY;
  UI.aiT=setTimeout(()=>{UI.aiT=null;if(!G||G.over||UI.pause)return;if(UI.sel&&UI.sel.off){schedule();return}
    let st=null;try{st=aiStep()}catch(e){console.error(e);return}if(!st)return;if(isHuman(st.seat))return;
    const go=()=>{UI.aiT=null;if(!G||G.over||UI.pause)return;if(legal(st.m,st.seat)){refresh();return}applyMove(st.m,st.seat)};
    if(ANIM&&st.m.a==='dual'){try{announce(st.m,st.seat)}catch(e){}UI.aiT=setTimeout(go,620/UI.speed)}else go()},d)}
// ---------- the real-time clock (timed jobs) ----------
function timedJob(){return !!(G&&UI.rt)}
function clockLeft(K){const ms=K.ms;if(ms.timer)return {left:ms.timer.show,real:ms.timer.left,label:'Clock'};if(ms.redTide)return {left:ms.redTide.left,real:ms.redTide.left,label:'Air'};
  if(ms.bus){const e=ms.bus.finalEnd!=null?ms.bus.finalEnd:ms.bus.ends;return e!=null?{left:Math.max(0,e-K.clock),real:Math.max(0,e-K.clock),label:ms.bus.finalEnd!=null?'Final dash':'Target'}:null}
  if(ms.bunker&&ms.bunker.ends!=null)return {left:Math.max(0,ms.bunker.ends-K.clock),real:Math.max(0,ms.bunker.ends-K.clock),label:'Objective'};
  if(ms.circus&&ms.circus.next!=null)return {left:Math.max(0,ms.circus.next-K.clock),real:999,label:'Next act'};return null}
function clockRunning(){return !isClient()&&timedJob()&&UI.started&&!UI.pause&&!UI.brief&&G&&!G.over&&G.phase==='turn'&&!G.q&&passTo()<0&&Date.now()>=UI.holdUntil&&!(document.hidden)}
function clockTick(){if(!clockRunning()){UI.clockAcc=0;sndLoop('clock_loop',false);return}
  UI.clockAcc+=.25*UI.tickRate;sndLoop('clock_loop',SND.on&&!!ANIM);if(UI.clockAcc>=1){const n=Math.floor(UI.clockAcc);UI.clockAcc-=n;tick(n)}}
const fmt=s=>{s=Math.max(0,Math.round(s));return Math.floor(s/60)+':'+String(s%60).padStart(2,'0')};
function togglePause(){if(isClient()){toast('Only the host can pause the job.');return}UI.pause=!UI.pause;if(!UI.pause){clearTimeout(UI.aiT);UI.aiT=null}toast(UI.pause?'Paused: the clock and the computer crew wait.':'Play resumes.');refresh()}
// ---------- music mood ----------
function audioMood(V){if(!G||G.over)return;const c=timedJob()?clockLeft(V):null;const low=(G.dial!=null&&G.dial<=1)||(G.ms.rf&&G.ms.rf.at>=10)||(c&&c.real<30);musicMood(low?'tension':'main')}
function tid(u){return 'g'+(UI.gameN||0)+'u'+u}
function uOf(id){const m=/u(\d+)$/.exec(String(id));return m?+m[1]:null}
function kitReset(){UI.gameN=(UI.gameN||0)+1;UI.fuseG=null;UI.fuseMax=0;UI.sel=null}
function shortEq(id){return ({eq1:'Tag two different neighbours',eq2:'Trade a wire face down',eq3:'Probe three wires',eq4:'Show one of your values',eq5:'Probe a whole stand',eq6:'Fuse back one step',eq7:'Wake spent tools',eq8:'Everyone says yes or no',eq9:'Your miss burns nothing',eq10:'Say two values',eq11:'Skip, pick who is next',eq12:'Tag two equal neighbours',eqY:'Two more gear cards',eq22:'Mark a lone value',eq33:'Used gear works again',eq99:'Solo-cut two',eq1010:'Cut a random number',eq1111:'Pull a crewmate wire'})[id]||''}
function missionCards(V){const n=G.mission,M=MISSIONS[n],ms=V.ms;const o={mission:{number:n,name:M.nm,text:M.text,difficulty:Math.min(5,1+Math.floor((n-1)/13))},numbers:[],constraints:[],challenges:[]};
  if(ms.gate){o.numbers=ms.gate.vals.map((v,i)=>({value:v,done:i<ms.gate.at}));o.sequence={side:ms.gate.req===4?'B':'A',at:ms.gate.at}}
  if(ms.fakeRed&&ms.fakeRed.v!=null)o.numbers=[{value:ms.fakeRed.v}];
  if(ms.eqDeckReveal&&ms.eqDeckReveal.face!=null)o.numbers=[{value:ms.eqDeckReveal.face}];
  if(ms.searchlight&&ms.searchlight.v!=null)o.numbers=[{value:ms.searchlight.v}];
  if(ms.special4&&ms.special4.v!=null)o.numbers=[{value:ms.special4.v,done:!!ms.special4.done}];
  if(ms.declare&&ms.declare.v!=null)o.numbers=[{value:ms.declare.v}];
  if(ms.line5)o.numbers=ms.line5.vals.map(v=>({value:v}));
  if(ms.meteor)o.numbers=ms.meteor.vals.map(v=>({value:v,done:!!G.fin[v]}));
  if(ms.volunteer&&ms.volunteer.v!=null)o.numbers=[{value:ms.volunteer.v}];
  if(ms.sir&&ms.sir.v!=null)o.numbers=[{value:ms.sir.v}];
  if(ms.robotLine&&ms.robotLine.line)o.numbers=ms.robotLine.line.map(v=>({value:v,done:!!G.fin[v]}));
  if(ms.math&&ms.math.up)o.numbers=ms.math.up.map(v=>({value:v}));
  if(ms.globCon&&ms.globCon.con)o.constraints.push({letter:ms.globCon.con});
  V.seats.forEach(q=>{if(q.con&&q.con!=='?')o.constraints.push({letter:q.con,seat:q.pos,faceDown:!!q.conDown});else if(q.con==='?')o.constraints.push({letter:'?',seat:q.pos,faceDown:true})});
  if(ms.challenges)o.challenges=ms.challenges.cards.map(c=>({n:c.id,done:!!c.dead}));
  if(ms.bunker)o.bunker={floor:(ms.bunker.f||0)+1};
  return o}
// which wires glow now
function toolN(t){return t==='dd'?2:t==='eq3'||t==='pt3'?3:t==='eq5'?99:1}
function eq5Slots(si){return G.st[si].w.map((x,k)=>k).filter(k=>{const x=G.st[si].w[k];return !x.cut&&!x.x&&!x.flip})}
function onTile(si,k){const V=UI.V;if(!V||V.seat<0||G.over)return;const sl=G.st[si].w[k];
  // a question that names wires
  if(V.q&&V.q.who===V.seat&&V.q.opts){const i=V.q.opts.findIndex(o=>o.d&&(o.d.u===sl.u||(o.d.st===si&&o.d.k===k)));if(i>=0){answer(i);return}toast('Pick one of the glowing wires, or use the buttons.');return}
  const sel=UI.sel;
  if(sel&&sel.mode==='choose'){const step=nextStep(sel);if(step&&step.board){const ok=selRemaining(sel).filter(m=>m[step.board[0]]===si&&m[step.board[1]]===k);if(ok.length){sel.fixed[step.board[0]]=si;sel.fixed[step.board[1]]=k;sel.picked=[{s:si,k}];sfx('select');refresh();return}}toast('That wire cannot be used for this.');return}
  if(sel&&sel.mode==='multi'){if(sl.cut)return;const i=sel.tg.findIndex(t=>t.s===si&&t.k===k);if(i>=0)sel.tg.splice(i,1);else if(sel.tg.length<sel.n)sel.tg.push({s:si,k});sfx('select');refresh();return}
  const L=V.legal;if(!L){toast(G.actor>=0?`It is ${nm(G.actor)}'s turn.`:'Not now.');return}
  if(sel&&sel.mode==='flipown'){toast('Pick which of your flipped wires you mean with the buttons.');return}
  const isTarget=L.plain.some(m=>m.st===si&&m.ks[0]===k);
  if(sel&&sel.mode==='dual'&&sel.tg.length){const st0=sel.tg[0].st;const need=toolN(sel.tool);
    const j=sel.tg.findIndex(t=>t.st===si&&t.k===k);if(j>=0){sel.tg.splice(j,1);if(!sel.tg.length)sel.v=null;sfx('select');refresh();return}
    if(si===st0&&need>sel.tg.length&&need!==99&&isTarget){sel.tg.push({st:si,k});sel.tg.sort((a,b)=>a.k-b.k);sfx('select');refresh();return}
    if(!isTarget){toast(ownerOf(si)===V.seat?'Point at a crewmate\'s wire, not your own.':'That wire cannot be pointed at now.');return}
    sel.tg=[{st:si,k}];if(sel.tool==='eq5')sel.tg=eq5Slots(si).map(x=>({st:si,k:x}));sel.v=keepV(sel);sfx('select');refresh();return}
  if(!isTarget){toast(ownerOf(si)===V.seat?'Those are your own wires: point at a crewmate\'s wire.':sl.cut?'That wire is already cut.':'That wire cannot be pointed at now.');return}
  UI.sel=Object.assign(sel&&sel.mode==='dual'?sel:{mode:'dual',tool:null,v:null,v2:null,two:null,fu:null},{tg:[{st:si,k}]});if(UI.sel.tool==='eq5')UI.sel.tg=eq5Slots(si).map(x=>({st:si,k:x}));UI.sel.v=keepV(UI.sel);sfx('select');refresh()}
function keepV(sel){if(sel.v==null)return null;return dualVals(sel).includes(sel.v)?sel.v:null}
function selValid(V){const s=UI.sel;if(!s)return true;if(s.off)return s.offSeat===V.seat||modeOf()!=='hot';if(!V.legal&&s.mode!=='choose')return false;if(s.mode==='choose'&&!s.off&&!V.legal)return false;return true}
// ---------- building a dual cut ----------
function dualVals(sel){const L=UI.V&&UI.V.legal;if(!L||!sel.tg.length)return [];const t=sel.tg[0];const src=sel.fu!=null?L.flip.filter(m=>m.fu===sel.fu):L.plain;
  let vs=[...new Set(src.filter(m=>m.st===t.st&&m.ks[0]===t.k).map(m=>m.v))];if(sel.tool)vs=vs.filter(v=>v!=='Y');return vs.sort((a,b)=>(a==='Y'?99:a)-(b==='Y'?99:b))}
function buildDual(sel){if(!sel||!sel.tg.length||sel.v==null)return null;const L=UI.V.legal;const t=sel.tg[0];
  const src=(sel.fu!=null?L.flip:L.plain).find(m=>m.st===t.st&&m.v===sel.v&&(sel.fu==null||m.fu===sel.fu));
  const m={a:'dual',st:t.st,ks:sel.tg.map(x=>x.k),v:sel.v};if(src)for(const key in src)if(!['a','st','ks','v'].includes(key))m[key]=src[key];
  if(sel.tool)m.tool=sel.tool;if(sel.two&&sel.v2!=null){m.two=sel.two;m.v2=sel.v2}if(sel.fu!=null){m.own='flip';m.fu=sel.fu}return m}
function heldCount(V,v){let n=0;for(const st of V.stands)if(st.mine)for(const x of st.slots)if(!x.cut&&x.v===v&&!x.flip)n++;return n}
// ---------- the generic chooser (equipment, tools, job actions with parameters) ----------
const STEPS={eq1:[{board:['s','k']}],eq12:[{board:['s','k']}],eq2:[{board:['s','k']},{key:'to'}],eq4:[{board:['s','k']},{key:'fv'}],eq6:[],eq7:[{key:'who'}],eq8:[{key:'v'}],eq9:[],eq11:[{key:'next'}],eq22:[{board:['s','k']}],
  eq1111:[{board:['ts','tk']},{key:'s'}],'item:sweep':[{key:'v'}],'item:handsets':[{board:['s','k2']},{key:'to'}],trip:[{board:['s','k']}],redcall:[{board:['s','k']}],accuse:[{key:'who'},{key:'con'}]};
function moveKey(m){return m.a==='eq'?m.id:m.a==='item'?'item:'+m.k:m.a}
function keyName(m){const k=moveKey(m);if(k.startsWith('item:'))return ITEMS[m.k].n;if(m.a==='eq')return EQUIP[m.id].n;return ({trip:'Point at a snare wire',redcall:'Call RED on a wire',accuse:'Accuse the mole',swapCon:'Swap your restriction',pass:'Pass',claim:'Claim the next turn',snip:'"Snip!" I will cut it',nosnip:'Nobody calls',snipReveal:'Reveal my reds',tada:'Shout "ta-da!"',signal:'Signal: I need oxygen',reveal:'Reveal my reds'})[k]||k}
function stepsOf(key){return STEPS[key]||[]}
function selRemaining(sel){return sel.opts.filter(m=>Object.keys(sel.fixed).every(k=>JSON.stringify(m[k])===JSON.stringify(sel.fixed[k])))}
function nextStep(sel){for(const st of stepsOf(sel.key)){const rem=selRemaining(sel);if(!rem.length)return null;
  if(st.board){if(!(st.board[0] in sel.fixed))return st;continue}if(st.key in sel.fixed)continue;
  const vals=new Set(rem.map(m=>JSON.stringify(m[st.key])));if(vals.size>1)return st}return null}
function paramLabel(key,v,m,V){if(key==='to'||key==='next')return nm(v);if(key==='who')return Array.isArray(v)?v.map(nm).join(' and '):nm(v);if(key==='v')return VNm(v);if(key==='fv')return 'Show "NOT '+v+'"';
  if(key==='con')return v+': '+(CONSTRAINTS[v]?CONSTRAINTS[v].n:'');if(key==='s')return 'Into your stand '+(seatStands(V.seat).indexOf(v)+1);return String(v)}
function startChoose(moves,off){const key=moveKey(moves[0]);UI.sel={mode:'choose',key,opts:moves,fixed:{},picked:[],off:!!off,offSeat:off?UI.V.seat:null};sfx('select');
  if(off&&(UI.aiT)){clearTimeout(UI.aiT);UI.aiT=null}refresh()}
// ---------- answering questions ----------
function answer(i){const V=UI.V;act({a:'q',i},V.seat)}
function sugText(m,V){if(!m)return '';switch(m.a){case 'dual':return `Say ${VNm(m.v)}${m.v2!=null?' or '+VNm(m.v2):''} at ${m.ks.length>1?nm(ownerOf(m.st))+'\'s wires '+m.ks.map(LET).join(', '):wireName(m.st,m.ks[0],V)}${m.tool?' with the '+toolName(m.tool):''}`;case 'solo':return `Solo cut your ${VNm(m.v)}s`;case 'reveal':return 'Reveal your reds';
  case 'eq':return 'Use '+EQUIP[m.id].n;case 'item':return 'Use '+ITEMS[m.k].n;case 'multi':return 'Point at '+m.tg.length+' wires at once';default:return keyName(m)}}
function toolHelp(t){return ({dd:'Twin Probe (once per job): point at 2 wires on one rack and say one number. A hit if either matches.',pt3:'Triple Probe (once per job): point at 3 wires on one rack and say one number. A hit if any matches.',eq3:'Point at 3 wires on one rack and say one number. A hit if any matches.',eq5:'Point at a whole rack and say one number. A hit if any wire matches.',pt10:'Say two numbers at once: a hit if the wire is either.',eq10:'Say two numbers at once: a hit if the wire is either.'})[t]||''}
function toolName(t){return t==='dd'?'Twin Probe':t==='pt3'?'Pocket Triple Probe':t==='pt10'?'Pocket Two-Value Probe':EQUIP[t]?EQUIP[t].n:t}
// the cached "what we know" for the current position
function wwk(V){if(V.seat<0)return null;const key=G.logN+':'+V.seat+':'+G.turn;if(UI.wwk&&UI.wwk.key===key)return UI.wwk.W;let W=null;try{W=whatWeKnow(V.seat,ANIM?80:24)}catch(e){console.error(e)}UI.wwk={key,W};return W}
function multiName(k){return ({red3:'Grab the three reds',four:'Point at all four',sevens:'Cut the four 7s',y3:'Point at the three yellows',lever:'Pull the lever (two yellows)',rush:'Yellow rush'})[k]||'All at once'}
// ---------- drawers ----------
function renderOpenDrawer(){const id=GX.open;if(!id||!G)return;if(id==='logd')renderLog();else if(id==='missiond')renderMission();else if(id==='geard')renderGear();else if(id==='setd')renderSettings()}
function renderLog(){const V=UI.V||view();$('#logbody').innerHTML=G?`<div class="loglist">${G.log.map(l=>`<div class="lg-${l.c||'n'}">${esc(nice(l.t,V))}</div>`).join('')}</div>`:'<p>No job yet.</p>'}
function mixHTML(n,np){const M=MISSIONS[n];const two=np===2&&M.two||{};const R=two.red!==undefined?two.red:M.red,Y=two.yel!==undefined?two.yel:M.yel;let h=`<span class="mix"><span class="mw b">1</span>…<span class="mw b">${M.blue}</span> <b>×4</b>`;
  if(Y){const n=Y.n==='players_max_4'?'1/player':Y.n;h+=` + ${Y.m==='of'?`<span class="mw y">${n}</span> of ${Y.of}`:`<span class="mw y">${n}</span>`} yellow`}if(R){h+=` + ${R.m==='of'?`<span class="mw r">${R.n}</span> of ${R.of}`:`<span class="mw r">${R.n}</span>`} red`}return h+'</span>'}
function fuseStart(n,np){const d=MISSIONS[n].dial;return d==='players'?np:d==='players+1'?Math.min(DIAL_MAX,np+1):d==null?'robot':d}
function ruleChips(n){const M=MISSIONS[n];const out=[];for(const r of M.rules){const d=RULE_DOC[r.k];if(d)out.push(d)}if(TOKFAM_DOC[M.tok])out.push(['eye','Tokens',TOKFAM_DOC[M.tok]]);if(INFO_DOC[M.info])out.push(['info','Opening',INFO_DOC[M.info]]);return out}
function renderMission(){const n=G.mission,M=MISSIONS[n],V=UI.V||view();const chips=ruleChips(n);
  let h=`<div class="mcard"><div class="mh"><b>${n}</b><h3>${esc(M.nm)}</h3></div><div class="mb"><p class="flav">${esc(BRIEFS[n]||'')}</p>
  <div class="tags"><span class="tag b">${mixHTML(n,G.np)}</span><span class="tag">${ico('fuse')}Fuse starts at ${fuseStart(n,G.np)}</span><span class="tag e">${ico('gear')}${G.eq.length} gear card${G.eq.length===1?'':'s'}</span>${M.audio||hasRule(n,'timer')?`<span class="tag t">${ico('clock')}Timed</span>`:''}</div>
  <p>${esc(M.text)}</p>${chips.length?chips.map(c=>`<div class="rule"><span class="ri">${ico(c[0])}</span><div><b>${esc(c[1])}</b><p>${esc(c[2])}</p></div></div>`).join(''):'<div class="rule"><span class="ri">'+ico('check')+'</span><div><b>No special rules</b><p>Just the basic game: dual cuts, solo cuts and the fuse.</p></div></div>'}
  ${cardsRow(V)}${jobNow(V)}</div></div>`;$('#missionbody').innerHTML=h}
function cardsRow(V){const mc=missionCards(V);let h='';if(mc.numbers.length)h+=`<div><div class="lbl">Number cards on the table</div><div class="mix">${mc.numbers.map((c,i)=>`<span class="mw b" style="width:30px;height:40px;font-size:1rem;${c.done?'opacity:.45':''}${mc.sequence&&mc.sequence.at===i?';outline:3px solid #8f5bff':''}">${esc(c.value)}</span>`).join('')}</div></div>`;
  if(mc.constraints.length)h+=`<div><div class="lbl">Restrictions</div>${mc.constraints.map(c=>`<div class="rule"><span class="ri" style="background:#ffd9d4;font:1.3rem var(--fd)">${esc(c.letter)}</span><div><b>${c.seat!=null?esc(nm(G.pos.indexOf(c.seat)))+': ':'Everyone: '}${c.letter==='?'?'hidden':esc(CONSTRAINTS[c.letter].n)}${c.faceDown&&c.letter!=='?'?' (turned down)':''}</b><p>${c.letter==='?'?'Face down.':esc(CONSTRAINTS[c.letter].text)}</p></div></div>`).join('')}</div>`;
  if(mc.challenges.length)h+=`<div><div class="lbl">Dares</div>${mc.challenges.map(c=>`<div class="rule"><span class="ri" style="background:#dff7e8;font:1.3rem var(--fd)">${c.n}</span><div><b>${esc(CHALLENGES[c.n].n)}${c.done?' (cannot be met any more)':''}</b><p>${esc(CHALLENGES[c.n].text)}</p></div></div>`).join('')}</div>`;return h}
function jobNow(V){const lines=jobState(V);return lines.length?`<div class="now"><b>Right now</b><ul class="ann">${lines.map(l=>`<li>${esc(l)}</li>`).join('')}</ul></div>`:''}
function jobState(V){const ms=V.ms,o=[];const N=s=>nm(s);
  if(ms.gate)o.push(`Order: ${ms.gate.vals.join(' → ')}. ${ms.gate.at>0?'Cleared: '+ms.gate.vals.slice(0,ms.gate.at).join(', ')+'. ':''}${ms.gate.at<ms.gate.vals.length?'Next in the order: '+ms.gate.vals[ms.gate.at]+' (cut '+ms.gate.req+' of it to open the next one).':'All order cards are cleared.'}`);
  if(ms.timer)o.push(`The clock shows ${fmt(ms.timer.show)}.`);if(ms.freeTurns&&ms.freeTurns.last!=null)o.push(`${N(ms.freeTurns.last)} played last and may not claim the next turn.`);
  if(ms.fakeRed&&ms.fakeRed.v!=null)o.push(`Blue ${ms.fakeRed.v} acts as red: never cut it.`);
  if(ms.eqCover)o.push('Covers: '+G.eq.map((e,i)=>e.cover!=null?`${EQUIP[e.id].n} needs two ${e.cover}s`:null).filter(Boolean).join('; ')+'.');
  if(ms.rookie&&ms.rookie.rookie!=null)o.push(`The rookie is ${N(ms.rookie.rookie)}.`);if(ms.liar&&ms.liar.liar!=null)o.push(`The fibber is ${N(ms.liar.liar)}.`);
  if(ms.eqDeckReveal)o.push(`Shown number: ${ms.eqDeckReveal.face!=null?ms.eqDeckReveal.face:'none'} (${ms.eqDeckReveal.left} cards left).`);
  if(ms.searchlight&&ms.searchlight.v!=null)o.push(`Searchlight on ${ms.searchlight.v}${ms.searchlight.who!=null?`: ${N(ms.searchlight.who)} must cut it`:''}.`);
  if(ms.xWire)o.push(ms.xWire.locked?'X wires are locked until every yellow is cut.':'X wires may be cut (but no gear can touch them).');
  if(ms.special4&&ms.special4.v!=null)o.push(`All-four value: ${ms.special4.v}${ms.special4.done?' (done)':''}.`);
  if(ms.declare)o.push(`Face-up number cards: ${ms.declare.up.join(', ')||'none'}${ms.declare.v!=null?`. Called: ${ms.declare.v}`:''}.`);
  if(ms.mindRead&&ms.mindRead.counts)o.push('Secret cards in hand: '+ms.mindRead.counts.map((c,i)=>N(i)+' '+c).join(', ')+'.');
  if(ms.bus)o.push(`Targets: ${ms.bus.tg.join(', ')||'none'}${ms.bus.lock?' (only these may be cut)':''}.`);
  if(ms.globCon&&ms.globCon.con)o.push(`Shared restriction ${ms.globCon.con}: ${CONSTRAINTS[ms.globCon.con].text}`);
  for(const q of V.seats)if(q.con)o.push(`${q.nm}: restriction ${q.con==='?'?'hidden':q.con+(q.conDown?' (turned down)':': '+CONSTRAINTS[q.con].text)}`);
  if(ms.mole)o.push(ms.mole.hidden?'The weak link is still hidden.':'The weak link was found.');
  if(ms.line5)o.push(`Line: ${ms.line5.vals.join(' · ')}. The arrow points at ${ms.line5.head}.`);
  if(ms.circus)o.push(`Next act at ${fmt(ms.circus.next||0)} of play${ms.circus.tada?'. Shout "ta-da!" when you cut':''}.`);
  if(ms.robotPatrol)o.push(`The robot stands on ${ms.robotPatrol.at}, walking ${ms.robotPatrol.dir>0?'up':'down'}, holding ${ms.robotPatrol.n} wire${ms.robotPatrol.n===1?'':'s'}.`);
  if(ms.oxygen)o.push(`Oxygen: reserve ${ms.oxygen.res}; `+V.seats.map(q=>q.nm+' '+q.ox).join(', ')+'.');
  if(ms.volunteer&&ms.volunteer.v!=null)o.push(`Card: ${ms.volunteer.v}${ms.volunteer.who!=null?`, called by ${N(ms.volunteer.who)}`:''}.`);
  if(ms.math&&ms.math.up)o.push(`Face-up cards: ${ms.math.up.join(', ')}.`);
  if(ms.sir&&ms.sir.v!=null)o.push(`The boss calls ${ms.sir.v}${ms.sir.who!=null?' for '+N(ms.sir.who):''}.`);
  if(ms.robotFuse)o.push(`The robot fuse is at ${ms.robotFuse.at} of 12.`);if(ms.redTide)o.push(`${ms.redTide.pile} reds still in the pile; ${fmt(ms.redTide.left)} left.`);
  if(ms.challenges)o.push('Dares: '+ms.challenges.cards.map(c=>`${CHALLENGES[c.id].n}${c.dead?' (cannot be met)':''}`).join('; ')+(ms.challenges.done.length?`. Met: ${ms.challenges.done.length}`:'')+'.');
  if(ms.robotLine)o.push(`Robot on ${ms.robotLine.line[ms.robotLine.at]} in the line ${ms.robotLine.line.join(' ')}.`);
  if(ms.meteor)o.push(`Meteor values: ${ms.meteor.vals.map(v=>v+(G.fin[v]?' ✓':'')).join(', ')}.`);
  if(ms.hotPotato)o.push('Cards: '+ms.hotPotato.cards.map((c,i)=>`${N(i)} ${c.map(x=>x.v).join('/')}`).join('; ')+'.');
  if(ms.bunker){const b=ms.bunker;o.push(`Bunker ${b.f?'basement':'ground floor'}, crew on row ${b.r+1} column ${b.c+1}. Goal: ${b.goal}. Sides: up ${b.sides.U}, right ${b.sides.R}, down ${b.sides.D}, left ${b.sides.L}.`)}
  if(V.robot)o.push(`The robot holds ${V.robot.n} wire${V.robot.n===1?'':'s'}.`);
  for(const st of V.stands)if(st.side.length)o.push(`Beside ${nm(st.owner)}'s stand: `+st.side.map(t=>(t.mean==='none'?'no ':'')+VNm(t.v)).join(', ')+'.');
  return o}
function renderGear(){const V=UI.V||view();if(noGear()){$('#gearbody').innerHTML='<p><b>This training job has no equipment cards.</b> Your crew card still has its <b>Twin Probe</b>: once per job, point at two wires of one crewmate and say one value; if either matches, it is a hit. Gear cards appear in later jobs: they unlock when the crew cuts certain numbers, and this drawer will show them.</p>';return}let h='<p class="tiny">The row of cards on the table mat is the crew\'s equipment. A card is <b>locked</b> until the crew cuts the numbers named on it, then it is <b>ready</b> for one use (or every turn, if it says so) and then <b>used</b>. Personal tools sit on each player\'s crew card.</p><div class="eqgrid">';
  V.eq.forEach((e,i)=>{if(e.down||!e.id){h+=`<div class="eqc locked"><div class="et"><b>?</b>Face-down card</div><div class="eqb"><i class="eqp back"></i><div class="ex">It turns up during the job.</div></div><div class="es">face down</div></div>`;return}const E=EQUIP[e.id];
    h+=`<div class="eqc ${e.st}"><div class="et"><b>${E.v==='Y'?'Y':E.v}</b>${esc(E.n)}<span class="tm">${{any:'any time',turn:'your turn',start:'start of turn',instant:'instant'}[E.timing]}</span></div><div class="eqb"><i class="eqp" style="--ai:var(--a-${e.id})"></i><div class="ex">${esc(E.text)}</div></div><div class="es">${e.st==='locked'?`${ico('lock')} locked: cut ${E.need===4?'all four':'two'} ${E.v==='Y'?'yellows':E.v+'s'}${e.cover!=null?' and two '+e.cover+'s':''}`:e.st==='ready'?'ready to use'+(e.perm?' (every turn)':''):'used'}</div></div>`});
  h+='</div><h3>Crew and personal tools</h3><div class="eqgrid">';
  for(const q of V.seats){const c=q.ch?CHARS[q.ch]:null;const it=c?ITEMS[c.item]:null;h+=`<div class="eqc ${q.chUsed?'used':'ready'}"><div class="et" style="background:${SEATC[q.pos%5]}"><b>${q.i===G.captain?'★':''}</b>${esc(q.nm)}: ${esc(c?c.n:q.chDown?'face-down card':'no crew card')}</div><div class="eqb"><i class="eqp${c?'':' back'}"${c?` style="--ai:var(--a-${q.ch})"`:''}></i><div class="ex">${it?`<u class="eqt" style="--ai:var(--a-${c.item})"></u><b>${esc(it.n)}</b>: ${esc(it.text)}`:'No personal tool.'}</div></div><div class="es">${q.chUsed?'tool used':q.chDown?'face down':it?'tool ready':''}</div></div>`}
  $('#gearbody').innerHTML=h+'</div>'}
function renderRef(){const E=refEntries();let h='',sec='';for(const e of E){if(e.s!==sec){if(sec)h+='</div>';sec=e.s;h+=`<h3>${esc(sec)}</h3><div class="reflist">`}
    h+=`<div class="ref"><span class="rc">${e.c!=null?'×'+e.c:'·'}</span><div><b>${esc(e.n)}</b>${e.tags.map(t=>`<small>${esc(t)}</small>`).join('')}<br>${esc(e.t)}</div></div>`}
  $('#refbody').innerHTML=h+'</div>'}
// ---------- settings ----------
function saveSettings(){lsSet('sf_set',{speed:UI.speed})}
function loadSettings(){const s=lsGet('sf_set',{});if(s.speed)UI.speed=s.speed}
function renderSettings(){const sp=[[.5,'Slow'],[1,'Normal'],[2,'Fast'],[5,'Very fast']];
  $('#setbody').innerHTML=`<div class="setgrid">
  <div><div class="lbl">Sound</div><div class="row"><button class="btn${SND.on?' on':''}" data-a="snd" id="sndbtn">${ico('snd')}Sound ${SND.on?'on':'off'}</button><button class="btn${SND.music?' on':''}" data-a="mus" id="musbtn">${ico('music')}Music ${SND.music?'on':'off'}</button><button class="btn small" data-gx="musicd">${ico('music')}Pick songs</button></div></div>
  <div><div class="lbl">Pictures</div><div class="row"><button class="btn small${LOWGFX?' on':''}" data-a="gfx" id="gfxbtn">Low graphics ${LOWGFX?'on':'off'}</button></div></div>
  <div><div class="lbl">Computer crew speed</div><div class="row">${sp.map(([v,l])=>`<button class="btn small${UI.speed===v?' on':''}" data-a="speed" data-v="${v}">${l}</button>`).join('')}</div></div>
  <div><div class="lbl">Game</div><div class="row">${isClient()?`<button class="btn small" data-a="netleave">${ico('back')}Leave the online game</button>`:`${G&&!G.over?`<button class="btn small" data-a="pause">${ico(UI.pause?'play':'pause')}${UI.pause?'Resume':'Pause'}</button><button class="btn small" data-a="restart">${ico('flip')}Restart</button>`:''}<button class="btn small" data-a="newgame">${ico('map')}Jobs</button>`}</div></div>
  <div><div class="lbl">More</div><div class="row"><button class="btn small" data-gx="logd">${ico('scroll')}Log</button><button class="btn small" data-gx="refd">${ico('cards')}Cards</button><button class="btn small" data-gx="credd">${ico('info')}Credits</button><a class="btn small" href="cards.html" target="_blank" rel="noopener">${ico('cards')}Card list</a></div></div></div>${typeof GXH!=='undefined'?`<div><div class="lbl">Tips</div>${GXH.settingsHTML({rowClass:"row",btnClass:"btn small"})}</div>`:''}${typeof GXT!=='undefined'?`<div><div class="lbl">Learn</div><div class="row">${tutBtn('btn small')}</div></div>`:''}`}
// ---------- campaign progress ----------
function jobProg(){if(!UI.prog)UI.prog=lsGet('sf_camp',{v:1,jobs:{}});return UI.prog}
function unlocked(n){const c=jobProg();return n===1||!!(c.jobs[n-1]&&c.jobs[n-1].w)||!!(c.jobs[n]&&c.jobs[n].p)}
function recordResult(){if(!humans().length)return;const c=jobProg();const n=G.mission;const j=c.jobs[n]=c.jobs[n]||{p:0,w:0,best:null};j.p++;
  if(G.over.win){j.w++;const r={left:G.dial,turns:G.turn,np:G.np};if(!j.best||(r.left!=null&&(j.best.left==null||r.left>j.best.left))||(r.left===j.best.left&&r.turns<j.best.turns))j.best=r}lsSet('sf_camp',c)}



// ===================== tbl.js: the table (board-first view) =====================
// The whole screen is the table: a fuse that burns down, the crew's stands as rows of wire tiles, equipment cards on the felt and
// my own stand along the bottom edge. Every action is a tap or a drag on a piece: glowing pieces are the legal ones.
// Text: one status line of 8 words or fewer; everything else is shown (glows, coins, flips, sparks, a ghost finger).
const TBL={fxq:[],lay:null,sig:'',ann:null,drag:null,sayT:0,ghostSig:'',tray:'',lastG:null,vsig:''};
const TOKC={n:'b',y:'y',p:'p',c:'c',f:'f'};
function tokInfo(t){if(!t)return null;if(t.t==='n')return t.v==='Y'?{c:'y',s:'Y'}:{c:'b',s:String(t.v)};if(t.t==='y')return {c:'y',s:'Y'};
  if(t.t==='p')return {c:'p',s:t.v==='e'?'E':'O'};if(t.t==='c')return {c:'c',s:'×'+t.v};if(t.t==='f')return {c:'f',s:'≠'+(t.v==='Y'?'Y':t.v)};return null}
// ---------- what glows ----------
// returns {u:Map(uid -> kind), plates:Set(seat), solo:Set(value)}; kinds: val (a number I can say), solo (a solo cut), tgt (a wire to point at), opt (an answer), flip (my face-down wire), rev (reveal)
function glowInfo(V){const g={u:new Map(),plates:new Set()};
  if(!V||V.seat<0||G.over||UI.brief||passTo()>=0||UI.paused)return g;
  const me=V.seat,sel=UI.sel,L=V.legal;const add=(u,k)=>{if(u!=null&&!g.u.has(u))g.u.set(u,k)};const addSK=(si,k,kind)=>{const sl=G.st[si]&&G.st[si].w[k];if(sl)add(sl.u,kind)};
  if(V.q&&V.q.who===me&&V.q.opts){const q=V.q;if(q.kind==='designate'){for(const o of q.opts)if(o.d&&o.d.seat!=null)g.plates.add(o.d.seat);return g}
    for(const o of q.opts){const d=o.d||{};if(d.u!=null)add(d.u,'opt');else if(d.st!=null&&d.k!=null)addSK(d.st,d.k,'opt')}return g}
  if(sel&&sel.mode==='choose'){const step=nextStep(sel);if(step&&step.board){for(const m of selRemaining(sel))addSK(m[step.board[0]],m[step.board[1]],'tgt')}
    else if(step&&(step.key==='who'||step.key==='to'||step.key==='next')){for(const m of selRemaining(sel)){const v=m[step.key];(Array.isArray(v)?v:[v]).forEach(s=>g.plates.add(s))}}
    for(const t of sel.picked||[]){const sl=G.st[t.s]&&G.st[t.s].w[t.k];if(sl)g.u.set(sl.u,'sel')}return g}
  if(sel&&sel.mode==='multi'){for(const st of V.stands)st.slots.forEach(x=>{if(!x.cut)add(x.u,'tgt')});return g}
  if(!L)return g;
  const own=V.stands.filter(st=>st.mine);const mineSlots=[];own.forEach(st=>st.slots.forEach((x,k)=>mineSlots.push({st:st.i,k,x})));
  if(sel&&sel.mode==='flipown'){for(const m of L.flip)add(m.fu,'flip');return g}
  if(sel&&sel.mode==='dual'){
    if(sel.tg.length){const t0=sel.tg[0];const need=toolN(sel.tool);
      if(sel.tool==='eq5'){}else if(need>sel.tg.length)for(const m of L.plain)if(m.st===t0.st)addSK(m.st,m.ks[0],'tgt');
      for(const t of sel.tg)add(G.st[t.st].w[t.k].u,'sel');
      const full=sel.tool==='eq5'||need<=sel.tg.length;
      if(full){const vs=dualVals(sel).filter(v=>v!==sel.v||!sel.two);const pick=sel.two&&sel.v!=null?vs.filter(v=>v!==sel.v):vs;
        for(const m of mineSlots)if(!m.x.cut&&m.x.v!=null&&!m.x.flip&&pick.includes(m.x.v))add(m.x.u,'val')}
      return g}
    if(sel.v!=null){for(const m of (sel.fu!=null?L.flip:L.plain))if((m.v===sel.v||sel.fu!=null)&&(sel.fu==null||m.fu===sel.fu))addSK(m.st,m.ks[0],'tgt');
      for(const m of mineSlots)if(m.x.v===sel.v&&!m.x.cut)add(m.x.u,'sel');return g}
    if(sel.fu!=null){for(const m of L.flip)if(m.fu===sel.fu)addSK(m.st,m.ks[0],'tgt');add(sel.fu,'sel');return g}
    if(sel.tool||sel.two){for(const m of L.plain)addSK(m.st,m.ks[0],'tgt');return g}}
  // nothing chosen yet: crew wires I can point at, my numbers I can say, my solo cuts, my reveal
  for(const m of L.plain)addSK(m.st,m.ks[0],'tgt');
  const vals=new Set(L.plain.map(m=>m.v)),solos=new Set(L.solo.filter(m=>!m.flip).map(m=>m.v));
  for(const m of mineSlots){const x=m.x;if(x.cut||x.v==null||x.flip)continue;if(solos.has(x.v))add(x.u,'solo');else if(vals.has(x.v))add(x.u,'val')}
  if(L.flip.length||L.solo.some(m=>m.flip))for(const m of mineSlots)if(m.x.flip&&!m.x.cut)add(m.x.u,'flip');
  if(L.other.some(m=>m.a==='reveal'))for(const m of mineSlots)if(!m.x.cut)add(m.x.u,'rev');
  return g}
// ---------- tiles ----------
function tileHTML(x,si,k,mine,g){const known=x.v!=null;const col=known?(x.c==='r'?'r':x.c==='y'?'y':'b'):'';
  const gk=g.u.get(x.u);let cls='tile '+(mine?'mine':'crew')+(known?' known '+col:' back')+(x.cut?' cut':'')+(x.flip?' flip':'')+(x.x?' xw':'')+(gk&&gk!=='sel'?' glow g-'+gk:'')+(gk==='sel'?' sel':'');
  const face=known?(x.c==='r'?'R':x.c==='y'?'Y':String(x.v)):(mine&&!x.cut?'?':'');
  const small=known&&x.c!=='b'&&x.s!=null?`<small>${esc(String(x.s))}</small>`:'';
  const toks=(x.tok||[]).map(tokInfo).filter(Boolean).slice(0,2).map(t=>`<i class="coin c-${t.c}">${esc(t.s)}</i>`).join('');
  const not=(x.not||[]).length?`<em class="nt">≠${esc((x.not||[]).slice(0,3).map(VNm).map(s=>s==='yellow'?'Y':s).join(','))}</em>`:'';
  const lab=(mine?'Your wire ':'Wire ')+LET(k)+(known&&x.v!=null&&(mine||x.cut)?', '+VNm(x.v):'')+(x.cut?', cut':'');
  const attrs=`data-s="${si}" data-k="${k}" data-u="${x.u}" aria-label="${esc(lab)}"`;
  const inner=`<span class="f">${esc(face)}</span>${small}${not}${toks}<span class="wr"></span>`;
  return gk&&gk!=='sel'?`<button class="${cls}" ${attrs}>${inner}</button>`:`<div class="${cls}" ${attrs}>${inner}</div>`}
function sideHTML(st){if(!st.side||!st.side.length)return '';return `<span class="side">${st.side.map(t=>`<i class="coin c-${t.t==='y'||t.v==='Y'?'y':'b'}${t.mean==='none'?' no':''}">${t.v==='Y'?'Y':esc(t.v)}</i>`).join('')}</span>`}
function standHTML(V,st,mine,g){return `<div class="stand${mine?' mine':''}" data-st="${st.i}">${st.slots.map((x,k)=>tileHTML(x,st.i,k,mine,g)).join('')}${sideHTML(st)}</div>`}
function plateHTML(V,q,mine,g){const cur=!G.over&&decider()===q.i;const ox=V.ms.oxygen?`<u class="ox">O₂${q.ox}</u>`:'';const con=q.con&&!V.ms.mole?`<u class="cn${q.conDown?' dn':''}">${esc(q.con)}</u>`:'';
  const gl=g.plates.has(q.i);const star=q.i===G.captain?'<span class="star" title="Foreman">★</span>':'';
  const tool=q.ch&&ITEMS[CHARS[q.ch].item]?`<u class="tl${q.chUsed?' used':''}" style="--ai:var(--a-${CHARS[q.ch].item})" title="${esc(ITEMS[CHARS[q.ch].item].n)}"></u>`:'';
  const tag=gl?'button':'div';
  return `<${tag} class="plate${cur?' cur':''}${gl?' glow g-plate':''}${q.nUncut?'':' out'}${mine?' mine':''}" data-seat="${q.i}" style="--sc:${SEATC[posOf(q.i)%5]}"><i class="pdot"${q.ch&&!q.chDown?` style="--ai:var(--a-${q.ch})"`:''}></i><b>${esc(mine&&modeOf()==='solo'?'You':q.nm)}</b>${star}${q.human?'':ico('robot','pbot')}<em>${q.nUncut}</em>${tool}${con}${ox}</${tag}>`}
function crewOrder(V){const me=V.seat>=0?V.seat:kitMe();const o=[];for(let j=1;j<G.np;j++)o.push(G.pos.indexOf((posOf(me)+j)%G.np));return V.seat>=0?o:(function(){const a=[];for(let p=0;p<G.np;p++)a.push(G.pos.indexOf(p));return a})()}
// ---------- the fuse ----------
function fuseTotal(){if(G.dial==null)return G.ms.robotFuse?12:0;const M=MISSIONS[G.mission];let st=M.dial==='players'?G.np:M.dial==='players+1'?Math.min(DIAL_MAX,G.np+1):M.dial;if(G.twist&&G.twist.id==='short-fuse')st-=G.twist.param||1;st=Math.max(1,st);UI.fuseMax=Math.max(UI.fuseMax||0,st,G.dial);if(UI.fuseG!==G.seed+':'+G.mission){UI.fuseG=G.seed+':'+G.mission;UI.fuseMax=Math.max(st,G.dial)}return UI.fuseMax}
function fuseHTML(){const tot=fuseTotal();if(!tot)return '';const left=G.dial!=null?G.dial:Math.max(0,12-(G.ms.robotFuse?G.ms.robotFuse.at:0));const burnt=Math.max(0,Math.min(tot,tot-left));
  let seg='';for(let i=0;i<tot;i++)seg+=`<i class="${i<burnt?'ash':'rope'}${i===burnt?' next':''}"></i>`;
  return `<div class="fz${left<=1?' danger':''}" data-left="${left}" data-tot="${tot}"><span class="lit">${ico('fuse')}</span><div class="rp">${seg}<b class="spark" style="left:${(burnt/tot*100).toFixed(1)}%"></b></div><svg class="bm" viewBox="0 0 24 24" width="26" height="26">${ICO.bomb}</svg></div>`}
function trackHTML(V){if(V.validOff)return '';let h='';for(let v=1;v<=12;v++){if(V.blueMax&&v>V.blueMax)break;const done=V.valid.includes(v);h+=`<i class="cn12${done?' done':''}">${done?'✓':v}</i>`}return `<div class="trk">${h}</div>`}
function cutCountHTML(V){const tot=G.st.reduce((a,s)=>a+s.w.length,0),cut=G.st.reduce((a,s)=>a+s.w.filter(x=>x.cut).length,0);return `<div class="cc"><b>${cut}</b>/${tot}</div>`}
function clockHTML(V){const c=timedJob()?clockLeft(V):null;if(!c)return '';return `<div class="clk${c.real<30?' low':''}" id="timerpill">${ico('clock')}<span>${fmt(c.left)}${UI.pause?' ⏸':''}</span></div>`}
// ---------- the felt: gear cards and job chips ----------
function eqMovesFor(V,id){if(V.seat<0||G.over)return [];let ms=[];try{ms=validMoves(V.seat).filter(m=>m.a==='eq'&&m.id===id)}catch(e){}return ms}
function gearHTML(V){let h='';
  if(!noGear())V.eq.forEach((e,i)=>{if(e.down||!e.id){h+=`<div class="eqk lk" data-gx="geard"><b>?</b><span class="en">Face down</span></div>`;return}
    const E=EQUIP[e.id];const ms=e.st==='ready'?eqMovesFor(V,e.id):[];const gl=ms.length>0;const need=E.need===4?'4×':'2×';
    const badge=`<b>${E.v==='Y'?'Y':E.v}</b>`;
    const st=e.st==='locked'?`<i class="lkc">${ico('lock')}</i><span class="nd">${need}${E.v==='Y'?'Y':E.v}</span>`:'';
    const nm=E.n.replace(/ Probe$/,' Pr.');
    const art=` style="--ai:var(--a-${e.id})"`;
    h+=gl?`<button class="eqk art ${e.st} glow g-eq" data-eq="${e.id}"${art} aria-label="${esc(E.n)}">${badge}<span class="en">${esc(nm)}</span></button>`:`<div class="eqk art ${e.st}" data-gx="geard" role="button" tabindex="0"${art} aria-label="${esc(E.n)}, ${e.st}">${badge}<span class="en">${esc(nm)}</span>${st}</div>`});
  const mc=missionCards(V);
  if(mc.numbers.length)h+=`<div class="jc nums" data-gx="missiond" role="button" tabindex="0" aria-label="Number cards">${mc.numbers.map((c,i)=>`<i class="nc${c.done?' dn':''}${mc.sequence&&mc.sequence.at===i?' cur':''}">${esc(c.value)}</i>`).join('')}</div>`;
  for(const c of mc.constraints)if(c.seat==null)h+=`<div class="jc cn" data-gx="missiond" role="button" tabindex="0" aria-label="Rule card"><u>${esc(c.letter)}</u></div>`;
  if(mc.challenges.length)h+=`<div class="jc chl" data-gx="missiond" role="button" tabindex="0" aria-label="Dares">${mc.challenges.map(c=>`<i class="nc${c.done?' dn':''}">${c.n}</i>`).join('')}</div>`;
  const ms=V.ms;
  if(ms.robotPatrol)h+=`<div class="jc rb" data-gx="missiond" role="button" tabindex="0" aria-label="Robot">${ico('robot')}<b>${ms.robotPatrol.at}</b></div>`;
  if(ms.robotLine&&ms.robotLine.line)h+=`<div class="jc rb" data-gx="missiond" role="button" tabindex="0" aria-label="Robot">${ico('robot')}<b>${ms.robotLine.line[ms.robotLine.at]}</b></div>`;
  if(V.robot)h+=`<div class="jc rb" data-gx="missiond" role="button" tabindex="0" aria-label="Robot">${ico('robot')}<b>${V.robot.n}</b></div>`;
  if(ms.oxygen)h+=`<div class="jc ox" data-gx="missiond" role="button" tabindex="0" aria-label="Oxygen">${ico('bubble')}<b>${ms.oxygen.res}</b></div>`;
  if(ms.bunker)h+=`<div class="jc bk" data-gx="missiond" role="button" tabindex="0" aria-label="Bunker floor">${ico('map')}<b>${(ms.bunker.f||0)+1}</b></div>`;
  const M=V.markers||{};if(!V.validOff&&((M.red||[]).length||(M.yel||[]).length))h+=`<div class="jc mk" data-gx="missiond" role="button" tabindex="0" aria-label="Candidate wires">${(M.red||[]).map(s=>`<i class="mkr r">${esc(s)}</i>`).join('')}${(M.yel||[]).map(s=>`<i class="mkr y">${esc(s)}</i>`).join('')}</div>`;
  return h}
// ---------- the tray: answers that are not wires ----------
function shortOpt(l){let s=String(l||'');s=s.replace(/^Take /,'').replace(/ - .*$/,'').replace(/\s*\(.*\)\s*$/,'');const w=s.split(/\s+/);return w.length>6?w.slice(0,6).join(' ')+'…':s}
function chipLabelOpt(o,q){const d=o.d||{};let m=/hold no (\w+)/.exec(o.l||'');if(m)return 'No '+m[1];m=/^Give token (\w+) to (.+)$/.exec(o.l||'');if(m)return m[1]+' to '+m[2];m=/^(?:Token|Take|Lay a token for|Place)\s+(\w+)$/.exec(o.l||'');if(m)return m[1];if(q.kind==='draftCon'&&d.c&&CONSTRAINTS[d.c])return d.c+' '+CONSTRAINTS[d.c].n;return shortOpt(nice(o.l,UI.V))}
function trayItems(V){const items=[];const me=V.seat;if(me<0||G.over||UI.brief||passTo()>=0)return items;const sel=UI.sel;const L=V.legal;
  const grp=(moves,off)=>{const gs={};for(const m of moves){const k=moveKey(m);(gs[k]=gs[k]||[]).push(m)}return Object.keys(gs).map(k=>({k,ms:gs[k],off}))};
  if(V.q&&V.q.who===me&&V.q.opts){const q=V.q;if(q.kind==='designate')return items;
    q.opts.forEach((o,i)=>{const d=o.d||{};if(d.u!=null||(d.st!=null&&d.k!=null))return;items.push({t:'q',i,label:chipLabelOpt(o,q)})});return items}
  if(sel&&sel.mode==='choose'){const step=nextStep(sel);const rem=selRemaining(sel);const m0=sel.opts[0];
    if(step&&step.key&&!(step.key==='who'||step.key==='to'||step.key==='next')){const vals=[...new Set(rem.map(m=>JSON.stringify(m[step.key])))].map(x=>JSON.parse(x));vals.forEach(v=>items.push({t:'param',key:step.key,v,label:paramLabel(step.key,v,m0,V)}))}
    else if(!step&&rem.length>1)rem.forEach((m,i)=>items.push({t:'pick',i,label:shortOpt(nice(describeMove(m),V))}));
    items.push({t:'cancel',label:'✕',mine:1});return items}
  if(sel&&sel.mode==='multi'){items.push({t:'cancel',label:'✕',mine:1});return items}
  if(sel&&sel.mode==='flipown'){items.push({t:'cancel',label:'✕',mine:1});return items}
  if(L&&decider()===me){
    for(const m of L.special)items.push({t:'multi',kind:m.kind,n:m.tg.length,label:multiName(m.kind)});
    for(const g of grp(L.other.filter(m=>m.a!=='reveal'&&m.a!=='eq'&&!(noGear()&&m.a==='item')),false))items.push({t:'grp',k:g.k,label:keyName(g.ms[0])});
    const T=L.tools;const toolOn=t=>sel&&sel.tool===t;
    for(const t of ['dd','pt3','eq3','eq5'])if(T[t])items.push({t:'tool',tool:t,on:toolOn(t),label:toolName(t),mine:1});
    for(const t of ['pt10','eq10'])if(T[t])items.push({t:'two',tool:t,on:sel&&sel.two===t,label:toolName(t),mine:1});
    if(sel)items.push({t:'cancel',label:'✕',mine:1})}
  // any-time and rule moves for the waiting seat (claim, snip ...)
  const off=(V.off||[]);if(off.length)off.forEach((m,i)=>{if(!(noGear()&&(m.a==='eq'||m.a==='item')))items.push({t:'off',i,label:keyName(m),go:m.a==='claim'||m.a==='snip'})});
  if(!L||decider()!==me){let any=[];try{any=validMoves(me).filter(m=>m.a==='item')}catch(e){}for(const g of grp(any,true))if(!noGear())items.push({t:'grp',k:g.k,off:true,label:keyName(g.ms[0])})}
  else{let any=[];try{any=L.other.filter(m=>m.a==='item')}catch(e){}}
  return items}
function trayHTML(V,items,mineSide){return items.map((it,n)=>{if(!!it.mine!==!!mineSide)return '';const cls='chip'+(mineSide||items.filter(i=>!i.mine).length>3?' sm':'')+(it.t==='cancel'?' x':'')+(it.on?' on':'')+(it.go?' go':'')+(it.t==='q'||it.t==='param'||it.t==='pick'||it.t==='off'||it.t==='grp'||it.t==='multi'?' glow g-chip':'');
  return `<button class="${cls}" data-chip="${n}">${esc(it.label)}</button>`}).join('')}
// ---------- the status line (8 words or fewer) ----------
function sayText(V){if(!G)return '';if(G.over)return G.over.win?'Defused!':'BOOM!';if(UI.brief)return 'Ready?';const p=passTo();if(p>=0)return 'Pass the phone';
  const me=V.seat,s=decider();
  if(me<0)return s>=0?nm(s)+(G.q?' is choosing':' is thinking'):'Watching the crew';
  if(V.q&&V.q.who===me&&V.q.opts)return ({infoStd:'Tap one of your wires',tagPick:'Tag a wire',pickMatch:'Which wire is cut?',swapPick:'Pick a wire to give',designate:'Who must cut?',declare:'Turn a card',infoNeg:'Pick a number you lack',infoFalse:'Tag a wire with a lie',lackTag:'Tag one of your wires',draftCon:'Pick your rule',robotStand:'Which stand?',leakStand:'Which stand?',bkMove:'Where to?'})[V.q.kind]||shortOpt(nice(V.q.title,V));
  const sel=UI.sel;
  if(sel&&sel.mode==='choose'){const st=nextStep(sel);return st&&st.board?'Tap a glowing wire':st&&(st.key==='who'||st.key==='to'||st.key==='next')?'Tap a player':'Pick one'}
  if(sel&&sel.mode==='multi')return sel.n-sel.tg.length>0?`Tap ${sel.n-sel.tg.length} more wire${sel.n-sel.tg.length>1?'s':''}`:'Ready';
  if(sel&&sel.mode==='flipown')return 'Tap your face-down wire';
  if(V.legal&&s===me){
    if(sel&&sel.mode==='dual'){if(sel.tg.length){const need=toolN(sel.tool);if(need>sel.tg.length&&need!==99)return `Tap ${need-sel.tg.length} more wire${need-sel.tg.length>1?'s':''}`;return sel.two&&sel.v!=null?'Pick a second number':'Tap your number'}
      if(sel.v!=null)return 'Tap a glowing wire';if(sel.tool||sel.two)return sel.two?'Tap a wire':'Tap '+toolN(sel.tool)+' wires'}
    if(!V.legal.plain.length&&!V.legal.flip.length&&V.legal.solo.length)return 'Tap your glowing wires';
    return 'Tap a glowing wire'}
  if(s>=0&&s!==me)return isHuman(s)?nm(s)+"'s turn":nm(s)+(G.q?' is choosing':' is thinking');
  if(G.step==='claim')return 'Claim the turn!';if(G.step==='snip')return 'Call it?';return 'Wait a moment'}
function setSay(t,hold){const el=document.getElementById('say');if(!el)return;if(hold){TBL.sayT=Date.now()+hold;el.textContent=t;el.classList.add('flash');setTimeout(()=>el.classList.remove('flash'),hold);return}if(Date.now()<TBL.sayT)return;el.textContent=t}
function toast(t){setSay(String(t).split(/\s+/).slice(0,8).join(' '),1700);const l=document.getElementById('live');if(l)l.textContent=t}
// ---------- the whole table ----------
function renderTable(V){if(!G)return;const tb=document.getElementById('tb');if(!tb)return;
  const g=glowInfo(V);TBL.lastG=g;const me=V.seat>=0?V.seat:-1;
  // crew
  const order=crewOrder(V);let crew='';
  for(const s of order){const q=V.seats[s];const sts=V.stands.filter(st=>st.owner===s).sort((a,b)=>a.i-b.i);if(!sts.length)continue;
    crew+=`<div class="sg${decider()===s&&!G.over?' cur':''}${q.nUncut?'':' out'}" data-seat="${s}" style="--sc:${SEATC[posOf(s)%5]}">${plateHTML(V,q,false,g)}${sts.map(st=>standHTML(V,st,false,g)).join('')}</div>`}
  // mine
  let mine='';if(me>=0){const sts=V.stands.filter(st=>st.owner===me).sort((a,b)=>a.i-b.i);const q=V.seats[me];
    const T=V.legal?V.legal.tools:{};const toolBtns=[];
    mine=`<div class="sg me${decider()===me&&!G.over?' cur':''}" style="--sc:${SEATC[posOf(me)%5]}"><div class="mh">${plateHTML(V,q,true,g)}@@MC@@</div>${sts.map(st=>standHTML(V,st,true,g)).join('')}</div>`}
  const items=trayItems(V);TBL.items=items;mine=mine.replace('@@MC@@',trayHTML(V,items,true));
  const set=(id,h,sig)=>{const el=document.getElementById(id);if(!el)return el;if(sig===undefined)sig=h;if(el._s!==sig){el._s=sig;el.innerHTML=h}return el};
  set('fuse',fuseHTML(),fuseHTML());set('cutc',cutCountHTML(V));set('track',trackHTML(V));set('clk',clockHTML(V));
  set('gear',gearHTML(V));set('crew',crew);set('mine',mine);
  const trh=trayHTML(V,items,false);const tr=set('tray',trh);tr.classList.toggle('on',trh.length>0);
  tb.classList.toggle('over',!!G.over);tb.classList.toggle('mineon',!!mine);tb.classList.toggle('dng',G.dial!=null&&G.dial<=1&&!G.over);
  setSay(sayText(V));
  renderOverlays(V);
  layoutTable();flushFx();placeGhost(V)}
// tile sizes: as large as fit; stands wrap to more rows rather than shrink below a thumb
function fitSize(counts,W,H,o){const g=o.gap;const ratio=o.ratio;let best=null;
  for(let tw=o.max;tw>=o.min;tw--){const cols=Math.max(1,Math.floor((W+g)/(tw+g)));const th=Math.round(tw*ratio);let h=0,rows=0;
    for(const grp of counts){h+=o.plate+o.seatGap;for(const n of grp){const r=Math.ceil(Math.max(1,n)/cols);rows+=r;h+=r*(th+g)}}
    if(h>H+1)continue;if(!best)best={tw,rows};else if(tw>=best.tw-4&&rows<best.rows)best={tw,rows}}
  return best?best.tw:o.min}
function balance(root,tw,g){root.querySelectorAll('.stand').forEach(st=>{const n=st.querySelectorAll('.tile').length;const side=st.querySelector('.side');const W=st.parentNode.clientWidth||st.clientWidth;const maxc=Math.max(1,Math.floor((W+g)/(tw+g)));const rows=Math.ceil(n/maxc);const cols=Math.max(1,Math.ceil(n/Math.max(1,rows)));st.style.maxWidth=(cols*(tw+g)+(side?44:0))+'px'})}
function layoutTable(){const tb=document.getElementById('tb');if(!tb||!G)return;const W=tb.clientWidth,H=tb.clientHeight;if(W<50||H<50)return;
  const crew=document.getElementById('crew'),mine=document.getElementById('mine'),felt=document.getElementById('felt'),gear=document.getElementById('gear');
  document.documentElement.classList.toggle('short',window.innerHeight<640);
  const land=W>H*1.15&&W>=600;tb.classList.toggle('land',land);
  const plate=window.innerHeight<640?20:24;
  const cs=[...crew.querySelectorAll('.sg')].map(s=>[...s.querySelectorAll('.stand')].map(st=>st.querySelectorAll('.tile').length));
  const ms=[...mine.querySelectorAll('.stand')].map(st=>st.querySelectorAll('.tile').length);
  const used0=[...tb.children].filter(e=>e!==felt&&e!==mine&&getComputedStyle(e).position!=='absolute'&&!e.hidden).reduce((a,e)=>a+e.offsetHeight,0);
  const gh=gear.offsetHeight,cw=W-12;const maxM=land?52:60;
  const crewFit=ch=>{if(land&&cs.length>1){const half=Math.ceil(cs.length/2);return Math.min(fitSize(cs.slice(0,half),(cw-10)/2,ch,{gap:3,ratio:1.3,min:22,max:54,plate,seatGap:6}),fitSize(cs.slice(half),(cw-10)/2,ch,{gap:3,ratio:1.3,min:22,max:54,plate,seatGap:6}))}
    return fitSize(cs,cw,ch,{gap:3,ratio:1.3,min:22,max:land?54:56,plate,seatGap:6})};
  const setMine=tw=>{mine.style.setProperty('--tw',tw+'px');mine.style.setProperty('--th',Math.round(tw*1.32)+'px');balance(mine,tw,4)};
  let tm=0,t1=0;crew.classList.toggle('two',land&&cs.length>1);
  if(ms.length){mine.style.maxHeight='';mine.style.overflow='';
    // my stand first, as big as it can be while the crew keeps a tile a thumb can still tap
    const capC=Math.min(40,crewFit(1e4));let pick=30;
    for(let tw=maxM;tw>=30;tw-=2){setMine(tw);const hm=mine.offsetHeight;const ch=H-used0-hm-gh;if(hm>H*(land?.5:.34))continue;const c=crewFit(ch);if(c>=capC){pick=tw;break}pick=tw}
    setMine(pick);tm=pick}
  const used=used0+(ms.length?mine.offsetHeight:0);
  const ch=Math.max(40,H-used-gh);t1=crewFit(ch);
  for(let i=0;i<24;i++){crew.style.setProperty('--tw',t1+'px');crew.style.setProperty('--th',Math.round(t1*1.3)+'px');balance(crew,t1,3);if(crew.scrollHeight<=crew.clientHeight+1||t1<=22)break;t1-=1}
  if(t1<30&&!gear.classList.contains('mini')&&gear.offsetHeight>30&&!TBL.relaid){TBL.relaid=1;gear.classList.add('mini');layoutTable();TBL.relaid=0;return}
  if(t1>=34&&gear.classList.contains('mini')&&!TBL.relaid&&!window.TBL_FORCEMINI){TBL.relaid=1;gear.classList.remove('mini');layoutTable();TBL.relaid=0;return}
  crew.classList.toggle('tn',t1<30);mine.classList.toggle('tn',tm<30);
  TBL.lay={W,H,tw:t1,tm};
  placeGhost(UI.V)}
// ---------- overlays: briefing, pass-the-phone, the end ----------
function renderOverlays(V){const ov=document.getElementById('over'),cv=document.getElementById('cover');if(!ov||!cv)return;
  const p=G.over?-1:passTo();
  if(UI.brief&&!G.over){const n=G.mission,M=MISSIONS[n];const chips=ruleChips(n).slice(0,4);cv.hidden=false;
    const h=`<div class="card2 briefc"><div class="bn">${n}</div><h2>${esc(M.nm)}</h2><div class="bch">${chips.map(c=>`<span class="rc">${ico(c[0])}<b>${esc(c[1])}</b></span>`).join('')}</div><button class="big go" data-a="briefok">Go</button></div>`;if(cv._s!==h){cv._s=h;cv.innerHTML=paintHTML(h)}}
  else if(p>=0){cv.hidden=false;const h=`<div class="card2 pass"><h2>${esc(nm(p))}</h2><button class="big go" data-a="take" data-seat="${p}">${ico('eye')}I am ${esc(nm(p))}</button></div>`;if(cv._s!==h){cv._s=h;cv.innerHTML=h}}
  else{cv.hidden=true;cv._s=''}
  if(G.over){if(UI.camp&&UI.campShown){ov.hidden=true}else{ov.hidden=false;const w=!!G.over.win;const next=G.mission<66?G.mission+1:null;const why=w?'':overWhy(G.over.why);
    const h=`<div class="card2 end ${w?'win':'lose'}"><div class="endart" aria-hidden="true"></div><h2>${w?'DEFUSED!':'BOOM!'}</h2>${why?`<p>${esc(why)}</p>`:''}${isClient()?'<p>Wait for the host</p>':`<div class="row">${w&&next&&!UI.camp?`<button class="big go" data-a="next">${ico('fwd')}Next job</button>`:''}<button class="big${w&&next&&!UI.camp?'':' go'}" data-a="again">${ico('flip')}Again</button><button class="big" data-a="board">${ico('map')}Jobs</button></div>`}</div>`;
    if(ov._s!==h){ov._s=h;ov.innerHTML=h}}}
  else{ov.hidden=true;ov._s=''}}
function paintHTML(h){return h}
function overWhy(w){w=String(w||'');if(/fuse|step|burn/i.test(w))return 'The fuse ran out';if(/red/i.test(w))return 'A red wire was cut';return w.split(/\s+/).slice(0,6).join(' ')}
// ---------- effects ----------
// diffFx() queues effects; they are played right after the DOM was rebuilt
function fx(name,arg){TBL.fxq.push([name,arg])}
function tileEl(u){return document.querySelector(`#tb .tile[data-u="${u}"]`)}
function sparks(el,n,col){const f=document.getElementById('fx'),tb=document.getElementById('tb');if(!el||!f||!tb)return;const r=el.getBoundingClientRect(),b=tb.getBoundingClientRect();
  for(let i=0;i<n;i++){const s=document.createElement('i');s.className='sp';const a=Math.random()*Math.PI*2,d=22+Math.random()*34;s.style.cssText=`left:${r.left-b.left+r.width/2}px;top:${r.top-b.top+r.height/2}px;--dx:${Math.cos(a)*d}px;--dy:${Math.sin(a)*d-10}px;background:${col||'#ffc928'}`;f.appendChild(s);setTimeout(()=>s.remove(),800)}}
function pop(el,txt,cls){const f=document.getElementById('fx'),tb=document.getElementById('tb');if(!el||!f||!tb)return;const r=el.getBoundingClientRect(),b=tb.getBoundingClientRect();const p=document.createElement('div');p.className='pop '+(cls||'');p.textContent=txt;
  p.style.left=Math.max(30,Math.min(b.width-30,r.left-b.left+r.width/2))+'px';p.style.top=Math.max(20,r.top-b.top-4)+'px';f.appendChild(p);setTimeout(()=>p.remove(),1100)}
function flushFx(){const q=TBL.fxq;TBL.fxq=[];if(!ANIM||!q.length)return;const tb=document.getElementById('tb');
  for(const [name,arg] of q){try{
    if(name==='cut'){const el=tileEl(arg);if(el){el.classList.add('snap');setTimeout(()=>el&&el.classList.remove('snap'),1000);sparks(el,9,'#ffe066');if(!TBL.popAt||Date.now()-TBL.popAt>500){TBL.popAt=Date.now();pop(el,'SNIP!','good')}}}
    else if(name==='miss'){const el=arg!=null?tileEl(arg):null;if(el){el.classList.add('buzz');setTimeout(()=>el.classList.remove('buzz'),800);sparks(el,6,'#ff7a3a')}
      const fz=document.querySelector('#fuse .fz');if(fz){fz.classList.add('burn');setTimeout(()=>fz.classList.remove('burn'),1200);const sp=fz.querySelector('.spark');if(sp)sparks(sp,14,'#ff9a3a')}pop(el||document.querySelector('#fuse .fz'),'BUZZ!','bad');tb.classList.add('shake');setTimeout(()=>tb.classList.remove('shake'),500)}
    else if(name==='phew'){const fz=document.querySelector('#fuse .fz');if(fz){fz.classList.add('phew');setTimeout(()=>fz.classList.remove('phew'),1200);pop(fz,'PHEW!','good')}}
    else if(name==='win'){tb.classList.add('winfx');setTimeout(()=>tb.classList.remove('winfx'),2500);document.querySelectorAll('#tb .tile.known').forEach((e,i)=>{if(i%3===0)sparks(e,2,'#8cf06a')})}
    else if(name==='boom'){tb.classList.add('boomfx');setTimeout(()=>tb.classList.remove('boomfx'),2500);const el=arg!=null?tileEl(arg):document.querySelector('#fuse .spark');if(el)sparks(el,26,'#ff5a1f')}
    else if(name==='coin'){const el=document.querySelector('#track .cn12.done:last-child');if(el){el.classList.add('flipc');setTimeout(()=>el.classList.remove('flipc'),900)}}
  }catch(e){console.error(e)}}}
// a teammate's move is announced for a moment before it happens: the pointer, the number
function announce(m,seat){if(!ANIM||!m||m.a!=='dual')return;const f=G.st[m.st]&&G.st[m.st].w[m.ks[0]];if(!f)return;const el=tileEl(f.u);if(!el)return;
  const fe=document.getElementById('fx'),tb=document.getElementById('tb');if(!fe||!tb)return;const r=el.getBoundingClientRect(),b=tb.getBoundingClientRect();
  const old=fe.querySelector('.say');if(old)old.remove();const d=document.createElement('div');d.className='say';
  const vv=m.v===undefined?'?':(m.v==='Y'?'Y':m.v)+(m.v2!=null?' / '+(m.v2==='Y'?'Y':m.v2):'');
  d.innerHTML=`<span style="--sc:${SEATC[posOf(seat)%5]}">${esc(nm(seat))}</span><b>${esc(vv)}?</b>`;
  d.style.left=Math.max(34,Math.min(b.width-34,r.left-b.left+r.width/2))+'px';d.style.top=Math.max(26,r.top-b.top-10)+'px';fe.appendChild(d);
  m.ks.forEach(k=>{const t=G.st[m.st].w[k];const e2=t&&tileEl(t.u);if(e2){e2.classList.add('aim');setTimeout(()=>e2.classList.remove('aim'),700)}});
  setTimeout(()=>d.remove(),900);sfx('select')}
// ---------- the ghost finger: shows the very first move ----------
function ghostPlan(V){if(!UI.ghost||G.over||UI.brief||passTo()>=0||V.seat<0)return null;const me=V.seat;
  if(V.q&&V.q.who===me&&V.q.kind==='infoStd'&&UI.ghost.info){const o=V.q.opts.slice().sort((a,b)=>{const cA=heldCount(V,cvOf(V,a.d.u)),cB=heldCount(V,cvOf(V,b.d.u));return cA-cB})[0];if(o)return {kind:'tap',u:o.d.u}}
  if(V.legal&&decider()===me&&!UI.sel&&UI.ghost.turn){const W=wwk(V);const m=W&&W.suggestion&&W.suggestion.m;if(!m)return null;
    if(m.a==='dual'&&!m.tool&&!m.two&&m.ks.length===1&&!m.own&&!legal(m,me)){const t=G.st[m.st].w[m.ks[0]];const mine=V.stands.filter(st=>st.mine).map(st=>st.slots).flat().find(x=>x.v===m.v&&!x.cut&&!x.flip);if(t&&mine)return {kind:'drag',from:mine.u,u:t.u}}
    if(m.a==='solo'&&!legal(m,me)&&!m.ep&&!m.flip){const mine=V.stands.filter(st=>st.mine).map(st=>st.slots).flat().find(x=>x.v===m.v&&!x.cut&&!x.flip);if(mine)return {kind:'tap',u:mine.u}}}
  return null}
function cvOf(V,u){for(const st of V.stands)for(const x of st.slots)if(x.u===u)return x.v;return null}
function placeGhost(V){const gh=document.getElementById('ghost');const tb=document.getElementById('tb');if(!tb)return;let plan=null;try{plan=V&&G&&UI.started?ghostPlan(V):null}catch(e){plan=null}
  const sig=plan?JSON.stringify(plan):'';if(!plan){if(gh)gh.remove();TBL.ghostSig='';return}
  const a=tileEl(plan.from!=null?plan.from:plan.u);if(!a){if(gh)gh.remove();return}
  const tbr=tb.getBoundingClientRect(),ar=a.getBoundingClientRect();let el=gh;if(!el){el=document.createElement('div');el.id='ghost';el.innerHTML='<svg viewBox="0 0 40 48" width="44" height="52"><path d="M14 22V8a3.5 3.5 0 0 1 7 0v12l9 3c3 1 5 3 5 7v6c0 6-4 10-10 10h-3c-5 0-8-2-10-6L6 31c-1-2 1-4 3-3l5 4z" fill="#fff" stroke="#1c1838" stroke-width="2.5" stroke-linejoin="round"/></svg>';tb.appendChild(el)}
  const x0=ar.left-tbr.left+ar.width*.5-14,y0=ar.top-tbr.top+ar.height*.55;el.style.left=x0+'px';el.style.top=y0+'px';el.dataset.kind=plan.kind;
  if(plan.kind==='drag'){const b=tileEl(plan.u);if(b){const br=b.getBoundingClientRect();el.style.setProperty('--dx',(br.left-tbr.left+br.width*.5-14-x0)+'px');el.style.setProperty('--dy',(br.top-tbr.top+br.height*.55-y0)+'px')}}
  TBL.ghostSig=sig}
function ghostDone(kind){if(!UI.ghost)return;if(kind==='info')UI.ghost.info=0;if(kind==='turn')UI.ghost.turn=0;lsSet('sf_ghost',{info:UI.ghost.info,turn:UI.ghost.turn});const gh=document.getElementById('ghost');if(gh)gh.remove()}
// ---------- input ----------
function tapTile(si,k){const V=UI.V;if(!V||V.seat<0||G.over||UI.brief)return;const own=ownerOf(si)===V.seat;
  if(UI.ghost&&UI.ghost.info&&V.q&&V.q.kind==='infoStd'&&own)ghostDone('info');
  if(own)onMine(si,k);else onTile(si,k)}
function autoFire(){const sel=UI.sel,V=UI.V;if(!sel||sel.mode!=='dual'||!sel.tg.length||sel.v==null)return false;if(sel.two&&sel.v2==null)return false;const need=toolN(sel.tool);if(need!==99&&sel.tg.length<need)return false;
  const m=buildDual(sel);if(!m)return false;const err=legal(m,V.seat);if(err){toast(err);return false}if(UI.ghost&&UI.ghost.turn)ghostDone('turn');act(m,V.seat);return true}
function onMine(si,k){const V=UI.V;const sl=G.st[si].w[k];const me=V.seat;
  if(V.q&&V.q.who===me&&V.q.opts){const i=V.q.opts.findIndex(o=>o.d&&(o.d.u===sl.u||(o.d.st===si&&o.d.k===k)));if(i>=0){answer(i);return}toast('Tap a glowing wire');return}
  const sel=UI.sel;if(sel&&(sel.mode==='choose'||sel.mode==='multi'))return onTile(si,k);
  const L=V.legal;if(!L||decider()!==me){toast(G.actor>=0?nm(G.actor)+"'s turn":'Not now');return}
  const view=V.stands[si].slots[k];if(view.cut)return;
  if(sel&&sel.mode==='flipown'){if(view.flip){UI.sel=Object.assign(sel.prev&&sel.prev.mode==='dual'?sel.prev:{mode:'dual',tg:[],v:null,v2:null,two:null},{fu:view.u,tool:null,v:null});sfx('select');refresh()}return}
  if(view.flip){// a face-down wire of mine: use it for a solo or point with it
    const soloF=L.solo.filter(m=>m.flip&&m.fu===view.u);if(soloF.length&&!L.flip.some(m=>m.fu===view.u)){act(soloF[0],me);return}
    if(L.flip.some(m=>m.fu===view.u)){UI.sel=Object.assign(sel&&sel.mode==='dual'?sel:{mode:'dual',tg:[],v:null,v2:null,two:null},{fu:view.u,tool:null});UI.sel.v=null;sfx('select');refresh();return}return}
  if(view.v==null)return;
  if(L.other.some(m=>m.a==='reveal')&&view.c==='r'){act({a:'reveal'},me);return}
  const v=view.v;
  if(sel&&sel.mode==='dual'&&sel.tg.length){const need=toolN(sel.tool);if(need!==99&&need>sel.tg.length){toast('Tap '+(need-sel.tg.length)+' more wire'+(need-sel.tg.length>1?'s':''));return}
    const vs=dualVals(sel);
    if(sel.two&&sel.v!=null&&sel.v2==null){if(v!==sel.v&&vs.includes(v)){sel.v2=v;sfx('select');if(!autoFire())refresh()}return}
    if(vs.includes(v)){sel.v=v;if(sel.v2===v)sel.v2=null;sfx('select');if(!autoFire())refresh();return}
    toast('You cannot say that here');return}
  if(sel&&sel.mode==='dual'&&sel.v===v&&!sel.tg.length){UI.sel=null;refresh();return}
  const solo=L.solo.filter(m=>m.v===v&&!m.flip);
  if(solo.length&&!(sel&&sel.mode==='dual'&&(sel.tool||sel.two))){const m=solo.find(x=>!x.ep)||solo[0];if(UI.ghost&&UI.ghost.turn)ghostDone('turn');act(m,me);return}
  const ok=L.plain.some(m=>m.v===v);if(!ok){toast('Nobody to point at');return}
  UI.sel=Object.assign(sel&&sel.mode==='dual'?sel:{mode:'dual',tool:null,tg:[],v:null,v2:null,two:null,fu:null},{v});sfx('select');refresh()}
// the crew wires: onTile (ui.js) sets the target; a number picked first fires here
function afterTile(){const V=UI.V;if(UI.sel&&UI.sel.mode==='multi'&&UI.sel.tg.length===UI.sel.n){const m={a:'multi',kind:UI.sel.kind,tg:UI.sel.tg};const err=legal(m,V.seat);if(err){toast(err);UI.sel.tg.pop();refresh();return}act(m,V.seat);return}
  if(UI.sel&&UI.sel.mode==='dual')autoFire();else if(UI.sel&&UI.sel.mode==='choose'&&V&&!nextStep(UI.sel)){const rem=selRemaining(UI.sel);if(rem.length===1)act(rem[0],V.seat)}}
document.addEventListener('click',e=>{const t=e.target.closest('#tb .tile.glow,#tb .tile.sel,#tb .plate.glow,#tb .chip,#tb .eqk.glow');if(!t){const tb=e.target.closest('#tb');if(tb&&UI.sel&&!e.target.closest('.tile,.chip,.plate,.eqk,button')&&G&&!G.over&&UI.sel.mode!=='choose'){UI.sel=null;refresh()}return}
  if(TBL.dragEnded&&Date.now()-TBL.dragEnded<300){return}
  if(t.classList.contains('tile')){const si=+t.dataset.s,k=+t.dataset.k;if(UI.sel&&UI.sel.mode==='dual'&&!UI.sel.v&&t.classList.contains('sel')&&t.classList.contains('crew')&&UI.sel.tg.length===1&&!UI.sel.tool){UI.sel=null;refresh();return}tapTile(si,k);afterTile();return}
  if(t.classList.contains('plate')){plateTap(+t.dataset.seat);return}
  if(t.classList.contains('eqk')){eqTap(t.dataset.eq);return}
  if(t.classList.contains('chip')){chipTap(+t.dataset.chip);return}});
function plateTap(seat){const V=UI.V;if(!V||V.seat<0)return;
  if(V.q&&V.q.who===V.seat&&V.q.kind==='designate'){const i=V.q.opts.findIndex(o=>o.d&&o.d.seat===seat);if(i>=0){answer(i);return}}
  const sel=UI.sel;if(sel&&sel.mode==='choose'){const step=nextStep(sel);if(step&&step.key){const vals=[...new Set(selRemaining(sel).map(m=>m[step.key]))];const hit=vals.find(v=>Array.isArray(v)?v.includes(seat):v===seat);if(hit!==undefined){sel.fixed[step.key]=hit;sfx('select');const rem=selRemaining(sel);if(rem.length===1&&!nextStep(sel)){act(rem[0],V.seat);return}refresh()}}}}
function eqTap(id){const V=UI.V;if(!V||V.seat<0)return;let moves=eqMovesFor(V,id);if(!moves.length)return;const k=moveKey(moves[0]);
  if(moves.length===1&&!stepsOf(k).length){act(moves[0],V.seat);return}startChoose(moves,!(V.legal&&decider()===V.seat))}
function chipTap(n){const V=UI.V;const it=TBL.items&&TBL.items[n];if(!it||!V)return;const me=V.seat;
  switch(it.t){
  case 'q':answer(it.i);return;
  case 'cancel':UI.sel=null;sfx('click');refresh();return;
  case 'param':{const s=UI.sel;s.fixed[it.key]=it.v;sfx('select');const rem=selRemaining(s);if(rem.length===1&&!nextStep(s)){act(rem[0],me);return}refresh();return}
  case 'pick':{const m=selRemaining(UI.sel)[it.i];if(m)act(m,me);return}
  case 'multi':UI.sel={mode:'multi',kind:it.kind,n:it.n,tg:[]};sfx('select');refresh();return;
  case 'tool':{const s=UI.sel&&UI.sel.mode==='dual'?UI.sel:(UI.sel={mode:'dual',tool:null,tg:[],v:null,v2:null,two:null,fu:null});s.tool=s.tool===it.tool?null:it.tool;s.fu=null;if(s.v==='Y')s.v=null;
    if(s.tg.length){const st=s.tg[0].st;s.tg=s.tool==='eq5'?eq5Slots(st).map(k=>({st,k})):s.tg.slice(0,1)}sfx('select');refresh();return}
  case 'two':{const s=UI.sel&&UI.sel.mode==='dual'?UI.sel:(UI.sel={mode:'dual',tool:null,tg:[],v:null,v2:null,two:null,fu:null});s.two=s.two===it.tool?null:it.tool;s.v2=null;sfx('select');refresh();return}
  case 'grp':{const k=it.k;let moves=it.off||!V.legal?validMoves(me).filter(m=>moveKey(m)===k):V.legal.eq.concat(V.legal.other).filter(m=>moveKey(m)===k);if(!moves.length)return;
    if(moves.length===1&&!stepsOf(k).length){act(moves[0],me);return}startChoose(moves,!!it.off||!V.legal);return}
  case 'off':{const m=(V.off||[])[it.i];if(m)act(m,me);return}}}
// dragging my own number onto a crewmate's wire
(function(){let d=null;const tb=()=>document.getElementById('tb');
  document.addEventListener('pointerdown',e=>{const t=e.target.closest&&e.target.closest('#mine .tile.glow.g-val,#mine .tile.glow.g-solo');if(!t||e.button>0)return;d={t,x:e.clientX,y:e.clientY,on:false,id:e.pointerId,el:null}},true);
  document.addEventListener('pointermove',e=>{if(!d||e.pointerId!==d.id)return;const dx=e.clientX-d.x,dy=e.clientY-d.y;
    if(!d.on&&Math.hypot(dx,dy)>12){d.on=true;const r=d.t.getBoundingClientRect();const c=d.t.cloneNode(true);c.className+=' dragc';c.style.cssText=`position:fixed;left:${r.left}px;top:${r.top}px;width:${r.width}px;height:${r.height}px;z-index:50;pointer-events:none;margin:0`;document.body.appendChild(c);d.el=c;d.r=r;d.t.classList.add('lift');sfx('select')}
    if(d.on){d.el.style.transform=`translate(${dx}px,${dy}px) scale(1.12) rotate(${Math.max(-12,Math.min(12,dx/8))}deg)`;const o=document.elementFromPoint(e.clientX,e.clientY);const crew=o&&o.closest&&o.closest('#crew .tile');document.querySelectorAll('#crew .tile.hov').forEach(x=>x.classList.remove('hov'));if(crew)crew.classList.add('hov')}},true);
  const end=e=>{if(!d||e.pointerId!==d.id)return;const was=d;d=null;if(!was.on)return;TBL.dragEnded=Date.now();if(was.el)was.el.remove();was.t.classList.remove('lift');document.querySelectorAll('#crew .tile.hov').forEach(x=>x.classList.remove('hov'));
    if(e.type==='pointercancel')return;const o=document.elementFromPoint(e.clientX,e.clientY);const ct=o&&o.closest&&o.closest('#crew .tile');const V=UI.V;if(!ct||!V||V.seat<0||!V.legal)return;
    const si=+ct.dataset.s,k=+ct.dataset.k;const sl=V.stands[si]&&V.stands[si].slots[k];const mv=V.stands.filter(s=>s.mine).map(s=>s.slots).flat().find(x=>x.u===+was.t.dataset.u);if(!sl||!mv||mv.v==null)return;
    if(!V.legal.plain.some(m=>m.st===si&&m.ks[0]===k&&m.v===mv.v)){toast('Not that wire');return}
    if(ownerOf(si)===V.seat)return;UI.sel={mode:'dual',tool:null,tg:[{st:si,k}],v:mv.v,v2:null,two:null,fu:null};if(UI.ghost&&UI.ghost.turn)ghostDone('turn');autoFire()};
  document.addEventListener('pointerup',end,true);document.addEventListener('pointercancel',end,true)})();
