// ===================== Short Fuse: painted extras =====================
// card paintings (SF_ART, embedded), card backs, table, title and ending art (media/), music picker panel.
// Everything has a plain-colour fallback: the CSS keeps working if a file is missing or "Low graphics" is on.
const MEDIA='media/';
let LOWGFX=false;try{LOWGFX=localStorage.getItem('sf_gfx')==='low'}catch(e){}
const ART_URL={};
function artBoot(){if(typeof SF_ART==='undefined')return;
  for(const k in SF_ART){if(ART_URL[k])continue;try{const d=SF_ART[k],bin=atob(d.slice(d.indexOf(',')+1)),u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);ART_URL[k]=URL.createObjectURL(new Blob([u],{type:'image/webp'}))}catch(e){ART_URL[k]=''}}}
// paintings reach the cards as CSS variables --a-<key>; with Low graphics on they are simply not set, so the colour fallbacks show
function artApply(){const R=document.documentElement;R.toggleAttribute('data-lowgfx',LOWGFX);
  for(const k in ART_URL){if(!LOWGFX&&ART_URL[k])R.style.setProperty('--a-'+k,'url('+ART_URL[k]+')');else R.style.removeProperty('--a-'+k)}}
const unl=t=>{try{const u=GXC.unlocked().filter(x=>x.type===t);return u.length?u[u.length-1].id:null}catch(e){return null}};
const IMG_OK={};const preImg=f=>{const i=new Image();i.onload=()=>{IMG_OK[f]=1};i.src=MEDIA+f+'.webp'};
// ---- card backs: face-down equipment cards; the campaign unlock replaces the default
let backCur='';
function backApply(){const R=document.documentElement,id=unl('cardback')||'default';if(LOWGFX){R.style.removeProperty('--back-img');backCur='';return}
  if(id===backCur)return;backCur=id;R.style.setProperty('--back-img','url('+MEDIA+'back-'+id+'.webp)')}
// ---- tables: painted workbench behind the board (the CSS teal stays while it loads and if the file is missing)
const tblSeen={};let tblCur='';
function tableApply(){const R=document.documentElement,id=unl('table')||'workbench';
  if(LOWGFX){R.removeAttribute('data-timg');tblCur='';return}
  const f='table-'+id+(id==='workbench'&&innerHeight>innerWidth?'-phone':'');if(f===tblCur)return;   // the phone workbench when held upright
  const go=()=>{tblCur=f;R.style.setProperty('--tbl-img','url('+MEDIA+f+'.webp)');R.dataset.timg='1'};
  if(tblSeen[f])return go();const im=new Image();im.onload=()=>{tblSeen[f]=1;go()};im.src=MEDIA+f+'.webp'}
// ---- title key art behind the start screen
function titleArt(){const R=document.documentElement,s=document.getElementById('start');if(!s)return;
  if(LOWGFX){s.classList.remove('art');return}
  if(R.dataset.tart){s.classList.add('art');return}
  const im=new Image();im.onload=()=>{R.dataset.tart='1';const s2=document.getElementById('start');if(s2&&!LOWGFX)s2.classList.add('art')};im.src=MEDIA+'title.webp'}
// ---- end art: the painted banner is in the result card (renderOverlays); here we only pick the picture
function endArt(){const R=document.documentElement;R.style.setProperty('--end-win','url('+MEDIA+'end-win.webp)');R.style.setProperty('--end-lose','url('+MEDIA+'end-lose.webp)')}
// ---- music panel: five slots, two songs each, plus shuffle and off
function renderMusic(){const b=document.getElementById('musicbody');if(!b)return;
  let vol=.45;try{vol=GA.state().musVol}catch(e){}
  const on=SND.music;
  const chip=(cls,at,label)=>`<button type="button" class="mchip${cls}" ${at}>${label}</button>`;
  let h=`<div class="mtop">${chip(on?' on':'','data-a="mmus"','Music: '+(on?'on':'off'))}<label class="mvol">Volume <input type="range" id="mvol" min="0" max="1" step=".05" value="${vol}" aria-label="Music volume"></label></div>`;
  const allOn=MLOOPS.every(k=>MUS.pick[k]==='all');h+=`<div class="mtop">${chip(allOn?' on':'','data-a="mall"','⇄ Shuffle all songs')}</div>`;
  for(const [k,nm] of MSLOTS){const cur=MUS.pick[k],act=SND.slot===k&&on&&cur!=='off'&&!MUS.prev;
    let row='';
    for(const v of 'ab')row+=chip(cur===v?' on':'',`data-a="mpick" data-s="${k}" data-c="${v}"`,esc(MTITLE[k+'-'+v]));
    row+=chip(cur==='shuffle'?' on':'',`data-a="mpick" data-s="${k}" data-c="shuffle"`,'⇄ Shuffle');
    if(MLOOPS.includes(k))row+=chip(cur==='all'?' on':'',`data-a="mpick" data-s="${k}" data-c="all"`,'⇄ All songs');
    row+=chip(cur==='off'?' on':'',`data-a="mpick" data-s="${k}" data-c="off"`,'Off');
    if(MUS.prev===k)row+=chip(' prev',`data-a="mprevx" data-s="${k}"`,'■ Stop preview');
    else if(!act&&cur!=='off'&&on)row+=chip(' prev',`data-a="mprev" data-s="${k}"`,'▶ Preview');
    h+=`<div class="mrow2"><h3>${nm}${act?'<small> playing now</small>':''}</h3><div class="mchips">${row}</div></div>`}
  b.innerHTML=h;const sl=document.getElementById('mvol');if(sl)sl.addEventListener('input',()=>{try{GA.setVolume('music',+sl.value)}catch(e){}})}
document.addEventListener('click',e=>{const t=e.target.closest('[data-a]');if(!t)return;const a=t.dataset.a;
  if(a==='mpick'){musicPick(t.dataset.s,t.dataset.c);renderMusic()}
  else if(a==='mall'){const on=MLOOPS.every(k=>MUS.pick[k]==='all');MLOOPS.forEach(k=>musicPick(k,on?'a':'all'));renderMusic()}
  else if(a==='mprev'){musicPreview(t.dataset.s);renderMusic()}
  else if(a==='mprevx'){musicPreviewStop();renderMusic()}
  else if(a==='mmus'){toggleMusic();renderMusic();try{renderSettings()}catch(x){}}
  else if(a==='gfx'){LOWGFX=!LOWGFX;try{localStorage.setItem('sf_gfx',LOWGFX?'low':'hi')}catch(x){}artApply();backApply();tableApply();titleArt();renderSettings()}});
function extrasBoot(){artBoot();artApply();endArt();backApply();tableApply();titleArt();
  ['back-default','back-clock-key','camp-brix','camp-tally','camp-wren','end-win','end-lose'].forEach(preImg);
  setInterval(()=>{try{backApply();tableApply();if(SND.wantMusic&&SND.music&&MUS.pick[SND.slot]==='all')musSync()}catch(e){}},800)}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',extrasBoot);else extrasBoot();



// ===================== tutor.js: the staged tutorial (shell/gx-tutor.js): a fixed little job that teaches every rule by doing it once =====================
// RULES CHECKLIST (read from the rules drawer RULES_HTML, the glossary, hlp.js rules cards and rules-test.js), and the step that teaches each one:
//   goal: cut every wire on every stand, together, before the fuse runs out ........ goal, win
//   your stand is face up to you, sorted low to high; the crew's wires are hidden ... mine, crew
//   the fuse: a miss burns a step, none left = boom; a red wire = boom ............... fuse, red
//   opening info token on one of your own wires; tokens are clues for everyone ....... token, tokens2
//   one action per turn, foreman first, then clockwise; teammates play the same ...... hit, crew1, crew2
//   dual cut: point at a crewmate's wire + name a number YOU hold; a hit cuts both .. point, name, hit
//   a miss: the fuse burns, a token shows the wire's true number, your wire stays hidden wrong1, wrong2, wrongres
//   using sort order and tokens as clues (teammates use the token the miss revealed) . crew2
//   validation token on the track when all four of a number are cut ................. crew2
//   solo cut: you hold every wire left of a number (all four, or the last two) ...... solo (and Plum does one in crew1)
//   equipment unlocks when two of its number are cut, then works once ................ hit (unlock), gear (use)
//   personal tool: the Twin Probe, once per job ....................................... probe
//   yellow wires: a yellow matches only a yellow, you must hold one to say "yellow" .. yellow1, yellow2
//   red wires: never point at one; a hand of only reds is revealed for you ............ red, win
// The staged job (never saved): three players (you = Amber, the foreman, then Teal, then Plum), 15 wires: blue 1-3 (four each), yellows 1.1 and 2.1, red 2.5.
//   You   : Y 2 2 2 R 3        Teal: 1 1 2 3        Plum: 1 1 Y 3 3      fuse 3 steps, one gear card (Rewind, unlocked by two 2s)
//   T1 you hit Teal's token-2 · T2 Teal hits your token-3 · T3 Plum solo-cuts his 3s · T4 you miss on Plum's 2nd wire (token 1) · T5 Teal uses that token ·
//   T6 Plum hits Teal's last 1 · T7 you use Rewind and cut the last yellow · T8 you solo your 2s, your red is revealed for you, defused.
// The computer never moves by itself in here: the steps that say "the crew plays" run its scripted moves (tutMove) and wait for them.
const TUT_GAME='short-fuse';
const TUT={eqv:null,mission:false};
const tutOn=()=>typeof GXT!=='undefined'&&GXT.active()&&!!UI.tut;
const tutBtn=cls=>typeof GXT==='undefined'?'':GXT.menuHTML({game:TUT_GAME,first:firstTime(),cls:cls,launch:tutStart});
function firstTime(){return !lsGet('sf_played',0)}
const tq=sel=>()=>{const e=document.querySelector(sel);return e&&e.getBoundingClientRect().width?e:null};
// ---------------------------------------------------------------- the fixed layout (wire ids: blue v = (v-1)*4+j, red v.5 = 48+v-1, yellow v.1 = 59+v-1)
const TUT_STANDS=[[59,4,5,6,49,8],[0,1,7,9],[2,3,60,10,11]];
const tutIdx=(si,id)=>G.st[si].w.findIndex(x=>x.id===id);
const tutEl=(si,id)=>()=>{if(!G)return null;const k=tutIdx(si,id);const sl=k>=0&&G.st[si].w[k];const e=sl&&tileEl(sl.u);return e&&e.getBoundingClientRect().width?e:null};
const myTwoK=()=>G.st[0].w.findIndex(x=>!x.cut&&cv(x.id)===2);
const tutMyTurn=()=>!!G&&!G.over&&G.phase==='turn'&&G.actor===0&&G.step==='act'&&!G.q&&!!(UI.V&&UI.V.legal);
const tutSelTo=(si,id)=>!!UI.sel&&UI.sel.mode==='dual'&&UI.sel.tg.length===1&&UI.sel.tg[0].st===si&&UI.sel.tg[0].k===tutIdx(si,id);
function tutRebuild(){const M=MISSIONS[67];
  G.q=null;G.ag=[];G.agI=0;G.log=[];G.logN=0;G.uid=0;G.captain=0;G.pos=[0,1,2];G.phase='setup';G.step=null;G.turn=0;G.round=0;G.hist=[];G.ann=[];G.marks=[];G.valid=[];G.fin={};G.over=null;G.winText='';G.tfx={};
  G.st=TUT_STANDS.map((ids,i)=>({i,pos:i,w:ids.slice().sort((a,b)=>sv(a)-sv(b)||a-b).map(newSlot),side:[]}));
  G.tot={1:4,2:4,3:4,Y:2};G.tokSup=clone(INFO_TOKENS);G.gone=[];G.box=[];G.aside=[];G.pile=[];G.markers={red:[2.5],redQ:0,redN:1,yel:[1.1,2.1],yelQ:0,yelN:2};
  G.eq=[{id:'eq6',st:'locked',down:0,cover:null,perm:0}];G.eqPool=[];G.eqDeck=[];G.eqOut=[];G.dial=3;G.stats={dual:0,dualOk:0,solo:0,miss:0,eqUse:0,turns:0};G.idle=0;
  lg('Training run: you, Teal and Plum. You are the foreman.','big');
  infoSetup(M);later('beginPlay');flow()}
function tutNew(){
  if(!MISSIONS[67]){MISSIONS[67]=Object.assign({},MISSIONS[1],{n:67,nm:'Training run',text:'A tiny practice bomb: 15 wires, three crew, one gear card.',pl:[3],blue:3,red:null,yel:null,eq:{n:0},rules:[],info:'std',tok:'num',audio:false,timer:null});BRIEFS[67]='A tiny practice bomb. Learn every rule here.';TUT.mission=true}
  if(TUT.eqv==null){TUT.eqv=EQUIP.eq6.v;EQUIP.eq6.v=2}
  UI.tut=true;UI.tutTok=(UI.tutTok||0)+1;
  try{GX.close()}catch(e){}hideStart();try{GXH.hide()}catch(e){}
  kitReset();clearTimeout(UI.aiT);UI.aiT=null;UI.rt=false;UI.started=false;UI.sel=null;UI.prev=null;UI.holder=-1;UI.offSeat=null;UI.campDone=0;UI.campShown=0;UI.wwk=null;UI.pause=false;UI.camp=null;UI.brief=null;UI.aiNotBefore=0;UI.lastPrompt=null;UI.ghost={info:0,turn:0};
  UI.started=true;
  newGame({np:3,mission:67,seats:['human','ai','ai'],level:'easy',names:DEFNAMES.slice(0,3),realtime:false,captain:0,seed:7});
  tutRebuild();UI.holder=0;UI.prev=snap();refresh()}
// leave the staged game: nothing of it is saved, and the board goes quiet behind the menu
function tutLeave(){UI.tut=false;UI.tutTok=(UI.tutTok||0)+1;clearTimeout(UI.aiT);UI.aiT=null;UI.started=false;UI.sel=null;UI.V=null;
  if(TUT.eqv!=null){EQUIP.eq6.v=TUT.eqv;TUT.eqv=null}
  if(TUT.mission){delete MISSIONS[67];delete BRIEFS[67];TUT.mission=false}
  G=null;try{GXH.hide()}catch(e){}
  for(const id of ['ghost']){const e=document.getElementById(id);if(e)e.remove()}
  for(const id of ['over','cover']){const e=document.getElementById(id);if(e){e.hidden=true;e._s=''}}
  for(const id of ['crew','mine','gear','tray','fuse','track','cutc','clk']){const e=document.getElementById(id);if(e){e._s=null;e.innerHTML=''}}}
// ---------------------------------------------------------------- the scripted crew
const tutWait=ms=>new Promise(r=>setTimeout(r,ms/Math.max(1,UI.speed||1)));
function tutMove(seat){
  if(G.q&&G.q.who===seat){if(G.q.kind!=='infoStd')return {a:'q',i:0};
    const want=seat===1?7:10;                                  // Teal shows her 2, Plum shows a 3
    const i=G.q.opts.findIndex(o=>{const f=findU(o.d.u);return f&&G.st[f.s].w[f.k].id===want});return {a:'q',i:Math.max(0,i)}}
  const T=G.turn;
  if(seat===1&&T===2)return {a:'dual',st:0,ks:[tutIdx(0,8)],v:3};                    // Teal uses your token: your 3
  if(seat===2&&T===3)return {a:'solo',v:3};                                           // Plum holds both 3s left
  if(seat===1&&T===5)return {a:'dual',st:2,ks:[tutIdx(2,3)],v:1};                     // Teal uses the token your miss put on Plum's wire
  if(seat===2&&T===6)return {a:'dual',st:1,ks:[tutIdx(1,1)],v:1};                     // Plum finishes the 1s
  return null}
const tutAlive=tok=>!!G&&UI.tut&&UI.tutTok===tok;
async function tutAct(seat,tok){const m=tutMove(seat);if(!m||!tutAlive(tok))return false;
  if(m.a==='dual'){try{announce(m,seat)}catch(e){}await tutWait(700)}else await tutWait(400);
  if(!tutAlive(tok))return false;
  const err=legal(m,seat);if(err){console.warn('tutor move rejected: '+err+' '+JSON.stringify(m));return false}
  applyMove(m,seat);await tutWait(1000);return true}
// the crew plays until it is the human's turn again
async function tutCrew(){const tok=UI.tutTok;for(let n=0;n<8&&tutAlive(tok)&&!G.over;n++){const s=sideToAct();if(s<0||isHuman(s))break;if(!await tutAct(s,tok))break}}
// ---------------------------------------------------------------- the steps
const tutCalm=()=>!document.querySelector('#tb .snap,#tb .buzz,#tb.shake,#fuse .burn,#fuse .phew');   // the cut / miss animation is over: the spotlight does not move
const hitTxt=()=>{const t=G.st[1].w[tutIdx(1,7)];return t&&t.cut};
function tutSteps(){return [
 {id:'goal',title:'The goal',say:()=>'Cut all '+G.st.reduce((a,s)=>a+s.w.length,0)+' wires before the fuse burns out. The whole crew wins or loses together.',target:tq('#cutc'),wait:null,ready:()=>!!G&&!!G.q},
 {id:'mine',title:'Your wires',say:'These wires are yours. Only you see the numbers. Every stand is sorted, lowest on the left.',target:tq('#mine'),wait:null},
 {id:'crew',title:'Their wires',say:'Teal and Plum hold the rest. You see only their backs, and they never see yours.',target:tq('#crew'),wait:null},
 {id:'fuse',title:'The fuse',say:'A wrong cut burns one step. When none is left, or a red wire is cut, the bomb explodes.',target:tq('#fuse'),wait:null},
 {id:'token',title:'Show a wire',say:'Everyone starts by showing one wire. Tap your 3: a token tells the crew its number.',target:tutEl(0,8),
   wait:{type:'tap',match:a=>a.what==='tile'&&a.own&&a.id===8},ready:()=>!!G&&!!G.q&&G.q.who===0&&G.q.kind==='infoStd'},
 {id:'tokens2',title:'Their tokens',say:'Teal and Plum each showed a wire too. Tokens are clues the whole crew can use.',target:tq('#crew'),wait:null,ai:tutCrew,ready:()=>!!G&&tutMyTurn()},
 {id:'point',title:'Point at a wire',say:'Your turn. Teal\'s token says 2. Tap that wire to point at it.',target:tutEl(1,7),
   wait:{type:'tap',match:a=>a.what==='tile'&&!a.own&&a.id===7},ready:()=>tutMyTurn()&&!UI.sel},
 {id:'name',title:'Name a number',say:'Now say a number you hold. Tap one of your 2s. If Teal has a 2, you both cut.',target:()=>{const k=myTwoK();return k>=0?tileEl(G.st[0].w[k].u):null},
   wait:{type:'tap',match:a=>a.what==='tile'&&a.own&&cv(a.id)===2&&a.k===myTwoK()},ready:()=>tutMyTurn()&&tutSelTo(1,7)},
 {id:'hit',title:'A hit!',say:'Match! Both 2s are cut and Rewind unlocked. One cut per turn, then it passes clockwise.',target:tq('#gear .eqk'),wait:null,ready:()=>hitTxt()&&!G.over&&tutCalm()},
 {id:'crew1',title:'Crew turns',say:'Teal used your token to cut your 3. Plum held every 3 left, so he cut them alone.',target:tq('#crew'),wait:null,ai:tutCrew,ready:()=>tutMyTurn()},
 {id:'wrong1',title:'A wrong guess',say:'Let\'s guess wrong on purpose. Plum\'s wires are hidden: tap his second wire.',target:tutEl(2,3),
   wait:{type:'tap',match:a=>a.what==='tile'&&!a.own&&a.id===3},ready:()=>tutMyTurn()&&!UI.sel},
 {id:'wrong2',title:'Name a number',say:'Say 2. It is really a 1, so this will miss.',target:()=>{const k=myTwoK();return k>=0?tileEl(G.st[0].w[k].u):null},
   wait:{type:'tap',match:a=>a.what==='tile'&&a.own&&cv(a.id)===2&&a.k===myTwoK()},ready:()=>tutMyTurn()&&tutSelTo(2,3)},
 {id:'wrongres',title:'A miss',say:()=>{const t=G.st[2].w[tutIdx(2,3)].tok[0];return 'Wrong! The fuse burned one step, and a token shows the true number: a '+(t?t.v:1)+'.'},
   target:tutEl(2,3),also:tq('#fuse'),wait:null,ready:()=>!!G&&G.dial===2&&G.st[2].w[tutIdx(2,3)].tok.length>0&&tutCalm()},
 {id:'crew2',title:'Using clues',say:'Teal used that token to cut a 1. Plum cut the last 1. Fully cut numbers get a green check.',target:tq('#track'),wait:null,ai:tutCrew,ready:()=>tutMyTurn()},
 {id:'probe',title:'Your Twin Probe',say:'Once per job, point at two wires and name one number. It hits if either wire matches.',target:tq('#mine .chip'),wait:null,ready:()=>tutMyTurn()&&!!document.querySelector('#mine .chip')},
 {id:'gear',title:'Use equipment',say:'Rewind is unlocked. Tap it to turn the fuse back one step. Gear works once.',target:tq('#gear .eqk.glow'),
   wait:{type:'tap',match:a=>a.what==='eq'&&a.id==='eq6'},ready:()=>tutMyTurn()&&!!document.querySelector('#gear .eqk.glow')},
 {id:'yellow1',title:'Yellow wires',say:'Every yellow is just "yellow". You hold one. Plum\'s last wire must be the other: tap it.',target:tutEl(2,60),
   wait:{type:'tap',match:a=>a.what==='tile'&&!a.own&&a.id===60},ready:()=>tutMyTurn()&&!UI.sel&&G.dial===3},
 {id:'yellow2',title:'Say yellow',say:'Name your yellow wire. A yellow can only be matched with another yellow.',target:tutEl(0,59),
   wait:{type:'tap',match:a=>a.what==='tile'&&a.own&&a.id===59},ready:()=>tutMyTurn()&&tutSelTo(2,60)},
 {id:'red',title:'Red wires',say:'Never point at red: the bomb explodes. If red is all you have left, it reveals itself.',target:tutEl(0,49),wait:null,ready:()=>tutMyTurn()&&!!G.st[2].w[tutIdx(2,60)].cut},
 {id:'solo',title:'Solo cut',say:'You hold every 2 left, so cut them alone. Tap one: both are cut, with no risk.',target:()=>{const k=myTwoK();return k>=0?tileEl(G.st[0].w[k].u):null},
   wait:{type:'tap',match:a=>a.what==='tile'&&a.own&&cv(a.id)===2&&a.k===myTwoK()},ready:()=>tutMyTurn()},
 {id:'win',title:'Defused!',say:'Every wire is cut: defused! Your last red was revealed for you. Win together, or lose together.',target:tq('#cutc'),wait:null,ready:()=>!!G&&!!G.over&&G.over.win}
]}
// ---------------------------------------------------------------- the kit hooks
function storyOpen(){if(typeof GXC==='undefined'||!window.CAMPAIGN)return;
  if(typeof GXT!=='undefined'&&!GXT.isDone(TUT_GAME))tutStart({prologue:true});else GXC.open()}
function tutStart(o){if(typeof GXT==='undefined')return;const pro=!!(o&&o.prologue);o=pro?o:null;const first=window.CAMPAIGN&&window.CAMPAIGN.chapters&&window.CAMPAIGN.chapters[0];
  try{const d=document.getElementById('offer');if(d)d.remove()}catch(e){}
  GXT.start({game:TUT_GAME,steps:tutSteps(),story:!!(window.CAMPAIGN&&typeof GXC!=='undefined'),
    endTitle:'You know the rules',endText:o?'Point, name, tokens, the fuse, gear, yellow, red. Now the Story begins.':'Point, name, tokens, the fuse, gear, yellow, red. Real jobs add twists: the lightbulb explains them.',
    endButtons:o&&first?[{id:'chapter',label:'Start chapter 1'}]:null,
    setup:tutNew,
    onDone:r=>{tutLeave();const c=r&&r.choice;
      if(c==='chapter'&&first){showStart();GXC.play(first.id)}
      else if(c==='story'&&typeof GXC!=='undefined'){showStart();GXC.open()}
      else showStart()},
    onExit:()=>{tutLeave();showStart();if(pro&&typeof GXC!=='undefined')GXC.open()}})}   // skipping the Story prologue opens the chapter map
// the first time a player taps Play, offer the tutorial once
function tutOffer(){if(typeof GXT==='undefined'||!firstTime()||GXT.isDone(TUT_GAME)||lsGet('sf_offered',0)||GXT.status(TUT_GAME).open)return false;
  lsSet('sf_offered',1);const d=document.createElement('div');d.id='offer';d.className='gxt-end';d.setAttribute('data-help','');d.setAttribute('role','dialog');d.setAttribute('aria-modal','true');d.setAttribute('aria-label','New here?');
  d.innerHTML='<div class="gxt-endc"><div class="gxt-et">New here?</div><div class="gxt-ex">Learn every rule in about 5 minutes, one tap at a time.</div><div class="gxt-eb"><button type="button" class="gxt-b pri" data-a="offeryes">Learn in 5 minutes</button><button type="button" class="gxt-b" data-a="offerno">Just play</button></div></div>';
  document.body.appendChild(d);return true}
// ---------------------------------------------------------------- the game tells the kit what the player does (before it is applied)
(function(){const o=tapTile;tapTile=function(si,k){
  if(tutOn()){const V=UI.V;const own=!!V&&V.seat>=0&&ownerOf(si)===V.seat;const sl=G.st[si]&&G.st[si].w[k];
    if(!sl||!GXT.act({type:'tap',what:'tile',si,k,own,id:sl.id}))return}
  return o(si,k)}})();
(function(){const o=eqTap;eqTap=function(id){if(tutOn()&&!GXT.act({type:'tap',what:'eq',id}))return;return o(id)}})();
(function(){const o=chipTap;chipTap=function(n){if(tutOn()&&!GXT.act({type:'tap',what:'chip',n}))return;return o(n)}})();
(function(){const o=plateTap;plateTap=function(s){if(tutOn()&&!GXT.act({type:'tap',what:'plate',s}))return;return o(s)}})();
// the computer never moves by itself in the staged job, nothing is saved, no result is recorded, and the win/lose card is the kit's end card
(function(){const o=schedule;schedule=function(){if(UI.tut)return;return o()}})();
(function(){const o=saveNow;saveNow=function(){if(UI.tut)return;return o()}})();
(function(){const o=recordResult;recordResult=function(){if(UI.tut)return;return o()}})();
(function(){const o=renderOverlays;renderOverlays=function(V){o(V);if(UI.tut){const ov=document.getElementById('over');if(ov)ov.hidden=true}}})();
// while the crew waits for its scripted move the status line says whose turn it is (the real "is thinking" would be a lie)
(function(){const o=sayText;sayText=function(V){const t=o(V);if(UI.tut&&G&&!G.over&&/ is thinking$| is choosing$/.test(t)){const s=decider();if(s>=0)return nm(s)+"'s turn"}return t}})();



// ===================== start.js: the start screen, story chapters, starting a job, boot =====================
// ---------- the start screen: one big Play button, the story, a job stepper ----------
function defaultSetup(){const s=lsGet('sf_setup',null);const d={job:1,np:3,seats:['human','ai','ai','ai','ai'],lv:'normal',chars:[],names:DEFNAMES.slice()};if(s)Object.assign(d,s,{names:(s.names||DEFNAMES).slice()});fixSetup(d);return d}
function fixSetup(s){s=s||UI.setup;if(!MISSIONS[s.job])s.job=1;const M=MISSIONS[s.job];if(!M.pl.includes(s.np))s.np=M.pl.find(x=>x>=s.np)||M.pl[M.pl.length-1];const ok=allowedChars(s.job,s.np);s.chars=s.chars||[];for(let i=0;i<5;i++)if(s.chars[i]&&!ok.includes(s.chars[i]))s.chars[i]='';return s}
function preset(v){const s=UI.setup;if(v==='solo')s.seats=['human','ai','ai','ai','ai'];if(v==='hot')s.seats=['human','human','human','human','human'];if(v==='watch')s.seats=['ai','ai','ai','ai','ai'];s.picked=v;renderStart()}
function seatMode(s){const k=s.seats.slice(0,s.np).filter(x=>x==='human').length;return k===0?'watch':k===1?'solo':'hot'}
function showStart(){if(isClient()){hideStart();return}clearTimeout(UI.aiT);UI.aiT=null;UI.setup=UI.setup||defaultSetup();sndLoop('hum',true);musicSlot('tavern');$('#start').hidden=false;renderStart();try{titleArt()}catch(e){}sndLoop('clock_loop',false)}
function hideStart(){$('#start').hidden=true;sndLoop('hum',false);if(G&&UI.started&&!G.over&&SND.slot==='tavern')musicStart()}
function campLine(){try{if(typeof GXC==='undefined'||!window.CAMPAIGN)return '';const p=GXC.progress(),ch=window.CAMPAIGN.chapters,n=ch.filter(c=>p.ch[c.id]&&p.ch[c.id].beaten).length;return n?n+' of '+ch.length:'10 chapters'}catch(e){return ''}}
function renderStart(){const s=UI.setup,n=s.job,M=MISSIONS[n],c=jobProg();const saved=savedGame();const tutFirst=firstTime()&&typeof GXT!=='undefined'&&!GXT.isDone(TUT_GAME);const nh=s.seats.slice(0,s.np).filter(x=>x==='human').length;const onl=isHost(),nOnl=onl?Math.min(s.np,NET.peers.length||1):0;
  let jobs='';for(const [a,b,label] of BOXES){jobs+=`<div class="box">${esc(label)}</div><div class="jobs">`;for(let k=a;k<=b;k++){const j=c.jobs[k];
      jobs+=`<button class="jt${j&&j.w?' done':''}${k===n?' sel':''}" data-a="job" data-n="${k}" aria-pressed="${k===n}" title="${esc(MISSIONS[k].nm)}"><b>${k}</b><span>${esc(MISSIONS[k].nm)}</span>${j&&j.w?'<i>✓</i>':''}${MISSIONS[k].audio||hasRule(k,'timer')?'<i class="t">⏱</i>':''}</button>`}jobs+='</div>'}
  const seatsTxt=nh===0?'Watch':nh===1?'You + computers':nh+' players, one phone';
  $('#start').innerHTML=`<div class="st-head"><svg viewBox="0 0 24 24" width="40" height="40" aria-hidden="true">${ICO.bomb}</svg><h1>Short Fuse</h1><span style="flex:1"></span>${G&&!G.over?'<button class="btn small" data-a="closestart">Back</button>':''}</div>
  <div class="st-body"><div class="st-main">
   ${tutFirst?tutBtn('big go'):''}
   <button class="big${tutFirst?'':' go'}" data-a="start">${ico('play')}${onl?'Start online ('+nOnl+')':nh===0?'Watch':'Play'}</button>
   <button class="big blue" data-a="story">${ico('map')}Story<small>${esc(campLine())}</small></button>
   ${tutFirst?'':tutBtn('big')}
   ${saved?`<button class="big" data-a="resume">${ico('fwd')}Continue<small>Job ${saved.G.mission}</small></button>`:''}
   <div class="jobrow"><button class="btn" data-a="jobprev" aria-label="Previous job">${ico('back')}</button><div class="jobcur"><b>${n}</b><span>${esc(M.nm)}</span>${MISSIONS[n].audio||hasRule(n,'timer')?'<i class="t">⏱</i>':''}</div><button class="btn" data-a="jobnext" aria-label="Next job">${ico('fwd')}</button></div>
   <div class="seg" role="group" aria-label="Crew size">${[2,3,4,5].map(k=>`<button class="btn small${s.np===k?' on':''}" data-a="np" data-v="${k}" ${M.pl.includes(k)?'':'disabled'}>${k}</button>`).join('')}</div>
   <div class="seg" role="group" aria-label="Computer level">${['easy','normal','hard'].map(l=>`<button class="btn small${s.lv===l?' on':''}" data-a="lv" data-v="${l}">${LV_NAME[l]}</button>`).join('')}</div>
   <details class="more"${UI.moreOpen||NET.on?' open':''}><summary>More</summary>
    <div class="seg"><button class="btn small${seatMode(s)==='solo'?' on':''}" data-a="preset" data-v="solo">${ico('user')}Solo</button><button class="btn small${seatMode(s)==='hot'?' on':''}" data-a="preset" data-v="hot">${ico('four')}One phone</button><button class="btn small${seatMode(s)==='watch'?' on':''}" data-a="preset" data-v="watch">${ico('eye')}Watch</button></div>
    ${onlineBlock()}<h2>${ico('map')} All jobs</h2>${jobs}</details>
  </div></div>`;paintIcons($('#start'))}
document.addEventListener('toggle',e=>{if(e.target&&e.target.classList&&e.target.classList.contains('more'))UI.moreOpen=e.target.open},true);
function savedGame(){try{const s=JSON.parse(localStorage.getItem(SAVE)||'null');return s&&s.G&&!s.G.over?s:null}catch(e){return null}}
function realtimeJob(n){const M=MISSIONS[n];return !!(M.audio||hasRule(n,'timer'))}
function startJob(s){if(isClient())return;lsSet('sf_played',1);s=Object.assign({},s);s.names=(s.names||DEFNAMES).slice();let plan=null;
  if(isHost()){plan=netPlan(s);if(plan.err){NET.err=plan.err;UI.netOpen=true;netRender();return}NET.err='';s.np=plan.np;s.seats=plan.seats;s.names=plan.names;fixSetup(s)}
  if(!plan&&!s.camp)lsSet('sf_setup',{job:s.job,np:s.np,seats:s.seats,lv:s.lv,chars:s.chars,names:s.names});UI.lastSetup=s.camp?UI.lastSetup:s;
  const seats=s.seats.slice(0,s.np);const chars={};let any=0;for(let i=0;i<s.np;i++)if(s.chars&&s.chars[i]){chars[i]=s.chars[i];any=1}
  UI.rt=realtimeJob(s.job);UI.started=false;clearTimeout(UI.aiT);UI.aiT=null;UI.sel=null;UI.prev=null;UI.holder=-1;UI.offSeat=null;UI.campDone=0;UI.campShown=0;UI.wwk=null;UI.pause=false;
  UI.camp=s.camp||null;UI.brief=(NET.on||isHost()||s.camp)?null:{n:s.job};UI.aiNotBefore=0;UI.lastPrompt=null;
  UI.ghost=lsGet('sf_ghost',{info:1,turn:1});if(s.camp&&s.camp.hints&&!lsGet('sf_ghost_'+s.camp.id,0)){lsSet('sf_ghost_'+s.camp.id,1);UI.ghost={info:1,turn:1}}if(s.camp&&!s.camp.hints)UI.ghost={info:0,turn:0};
  if(typeof GXH!=='undefined'){UI.ghost={info:0,turn:0};if(s.camp&&s.camp.hints)GXH.setEnabled(true)}
  const o={np:s.np,mission:s.job,seats,level:s.lv,names:s.names.slice(0,s.np),realtime:UI.rt};if(any){try{const ch=[];for(let i=0;i<s.np;i++)ch[i]=chars[i]||null;o.chars=ch}catch(e){}}
  if(s.captain!=null&&s.captain<s.np)o.captain=s.captain;if(s.seed!=null)o.seed=s.seed;if(s.twist)o.twist=s.twist;if(s.lvs)o.lv=s.lvs;
  kitReset();UI.started=true;hideStart();NET.starting=true;try{try{newGame(o)}catch(e){try{delete o.chars;newGame(o)}catch(e2){console.error(e2);UI.started=false;showStart();return}}
  if(plan)netBound(plan)}finally{NET.starting=false}
  if(humans().length===1&&!NET.on)UI.holder=humans()[0];
  UI.prev=snap();try{if(window.PerfHUD)PerfHUD.hitch()}catch(e){}musicStart();refresh()}
function resumeSaved(){const s=savedGame();if(!s)return;lsSet('sf_played',1);kitReset();G=s.G;UI.holder=s.ui.holder;UI.rt=!!s.ui.rt;UI.brief=null;UI.started=true;UI.prev=snap();UI.sel=null;UI.campDone=0;UI.campShown=0;UI.camp=null;UI.ghost={info:0,turn:0};hideStart();musicStart();refresh()}
function renderIdle(){const say=document.getElementById('say');if(say)say.textContent='Waiting for the host';for(const id of ['crew','mine','gear','tray','fuse','track','cutc','clk']){const e=document.getElementById(id);if(e){e._s=null;e.innerHTML=''}}const ov=document.getElementById('over');if(ov)ov.hidden=true}
// ---------- story chapters (the shared campaign kit) ----------
function campMetrics(G){const st=G.stats||{};return {won:!!(G.over&&G.over.win),misses:st.miss||0,left:G.dial!=null?G.dial:0,turns:G.turn,solos:st.solo||0,eqUsed:st.eqUse||0}}
function campStart(def){const np=def.setup.players||3;const lv=def.setup.level||'normal';const seats=['human'];for(let i=1;i<np;i++)seats.push('ai');
  const s={job:def.setup.mission,np,seats,lv,names:DEFNAMES.slice(),chars:[],camp:def,twist:def.twist&&def.twist.id?{id:def.twist.id,param:def.twist.param||1}:null};
  if(def.twist&&def.twist.id==='green-hand'){const l=[];for(let i=0;i<np;i++)l[i]=lv;if(np>1)l[np-1]='easy';s.lvs=l}
  startJob(s)}
function campOver(){if(!UI.camp||typeof GXC==='undefined'||!GXC.active())return;setTimeout(()=>{if(!G||!G.over)return;UI.campShown=1;try{document.getElementById('over').hidden=true}catch(e){}try{GXC.finish(G)}catch(e){console.error(e)}},ANIM?2200:0)}
function campInit(){if(typeof GXC==='undefined'||!window.CAMPAIGN)return;
  GXC.init({game:'short-fuse',artBase:'media/',headButtons:()=>{const b=document.createElement('button');b.type='button';b.className='gxc-ib';b.textContent='Tutorial';b.setAttribute('aria-label','Replay the tutorial');b.addEventListener('click',()=>{GXC.close();tutStart()});return [b]},data:window.CAMPAIGN,startChapter:campStart,isWon:G=>!!(G&&G.over&&G.over.win),metrics:campMetrics,
    onExit:()=>{UI.camp=null;showStart()},scores:g=>[g.seats.length?g.st.reduce((a,s)=>a+s.w.filter(x=>x.cut).length,0):0],seats:g=>g.seats.map((q,i)=>({name:i===0?'You':q.nm,me:i===0,ai:q.human?undefined:q.lv}))})}
// ---------- clicks on buttons that carry data-a ----------
document.addEventListener('click',e=>{const b=e.target.closest('[data-a]');if(!b||b.disabled)return;const a=b.dataset.a;const V=UI.V;
  if(netClick(a))return;
  switch(a){
  case 'take':UI.holder=+b.dataset.seat;UI.sel=null;sfx('click');refresh();return;
  case 'pause':togglePause();return;
  case 'xray':UI.xray=!UI.xray;refresh();return;
  case 'briefok':UI.brief=null;sfx('click');refresh();return;
  case 'next':startJob(Object.assign({},UI.lastSetup,{job:G.mission+1,captain:(G.captain+1)%G.np}));return;
  case 'again':if(UI.camp){return}startJob(Object.assign({},UI.lastSetup,{captain:G.captain}));return;
  case 'board':showStart();return;
  case 'snd':toggleSound();renderSettings();return;
  case 'mus':toggleMusic();renderSettings();return;
  case 'speed':UI.speed=+b.dataset.v;saveSettings();renderSettings();return;
  case 'newgame':GX.close();showStart();return;
  case 'restart':GX.close();if(UI.camp){const d=UI.camp;campStart(d)}else if(UI.lastSetup)startJob(UI.lastSetup);return;
  case 'job':UI.setup.job=+b.dataset.n;fixSetup();renderStart();sfx('select');return;
  case 'jobprev':UI.setup.job=Math.max(1,UI.setup.job-1);fixSetup();renderStart();sfx('select');return;
  case 'jobnext':UI.setup.job=Math.min(66,UI.setup.job+1);fixSetup();renderStart();sfx('select');return;
  case 'np':UI.setup.np=+b.dataset.v;fixSetup();renderStart();return;
  case 'lv':UI.setup.lv=b.dataset.v;renderStart();return;
  case 'preset':preset(b.dataset.v);return;
  case 'story':storyOpen();return;
  case 'start':if(!isHost()&&tutOffer())return;startJob(UI.setup);return;
  case 'offeryes':tutStart();return;
  case 'offerno':{const d=document.getElementById('offer');if(d)d.remove();startJob(UI.setup);return}
  case 'resume':resumeSaved();return;
  case 'closestart':if(G){hideStart()}return;
  }});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&UI.sel&&!GX.open){UI.sel=null;refresh()}});
// ---------- boot ----------
function boot(){GX.init({key:'sf'});paintIcons();loadSettings();
  GX.onShow=id=>{sfx('open');if(id==='rulesd')$('#rulesbody').innerHTML=RULES_HTML+GLOSS_HTML+'<h3>Credits</h3><p>Names, card text and art are original. <button class="btn small" data-gx="credd">Full credits</button></p>';if(id==='refd')renderRef();if(id==='musicd')renderMusic();if(id==='setd')renderSettings();if(G)renderOpenDrawer();else if(id==='logd'||id==='missiond'||id==='geard')$('#'+id+' .gx-drawer-body').innerHTML='<p>Start a job first.</p>'};
  GX.onClose=()=>sfx('close');
  setInterval(clockTick,250);setInterval(()=>{if(G&&UI.started&&timedJob()&&!G.over){const p=document.querySelector('#timerpill span');if(p&&UI.V){const c=clockLeft(knowledge(Math.max(0,UI.V.seat)));if(c){p.textContent=fmt(c.left)+(UI.pause?' ⏸':'');const cl=p.parentNode;if(cl)cl.classList.toggle('low',c.real<30)}}}},1000);
  campInit();netInit();showStart();if(UI.netOpen)netRender()}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();

